/* DIBANGKITKAN oleh scripts/sync-release.cjs dari release/*.json — jangan diedit langsung. */
window.RM_RELEASE={"version":"1.1.0-dev.46","production":"1.0.0","updated":"2026-10-23"};
window.RM_CHANGELOG=[{"version":"1.1.0-dev.46","date":"2026-10-23","summary":{"id":"Pita ringkasan kini berkarakter sama dengan kartu lain; sapaan header tanpa bayangan biru.","en":"Summary bands now look like every other card; the header greeting no longer has a blue shadow."},"entries":[{"id":"dev46-band","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Semua menu","en":"All menus"}},"title":{"id":"Pita ringkasan = kartu biasa","en":"Summary band = a regular card"},"detail":{"id":"Mode terang: warna, sudut, dan garis tipis sama dengan kartu lain, tanpa bayangan. Mode gelap: warna kartu yang sama, tanpa gradasi dan tanpa garis tepi. Kotak angka & rumus kas memakai warna lembut kartu (tanpa gradasi). Berlaku di 14 halaman baru, Kotak Masuk, Pekerjaan, dan Manajemen Label.","en":"Light: same colour, corners and hairline as other cards, no shadow. Dark: same card colour, no gradient, no outline. Applies to all redesigned pages, Inbox, Work and Label Management."}},{"id":"dev46-greet","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard","en":"Dashboard"}},"title":{"id":"Sapaan header tanpa bayangan biru","en":"Header greeting without the blue shadow"},"detail":{"id":"\"Halo, …\" di header bawaan masih membawa bayangan biru tua dari header biru lama; kini dihapus. Header dengan gambar unggahan tetap memakai bayangan netral agar teks terbaca di atas foto.","en":"The greeting kept a navy shadow from the old blue header; removed. Uploaded-image headers keep a neutral shadow for legibility."}}]},{"version":"1.1.0-dev.45","date":"2026-10-23","summary":{"id":"Pita ringkasan punya versi terang & gelap, warna penanda kembali sesuai Kamus Penanda, dan kartu dashboard sejajar.","en":"Summary bands get light & dark versions, indicator colours follow the Indicator Dictionary again, and dashboard cards line up."},"entries":[{"id":"dev45-band","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Semua menu","en":"All menus"}},"title":{"id":"Pita ringkasan: putih di mode terang, hitam di mode gelap","en":"Summary band: white in light mode, black in dark mode"},"detail":{"id":"Pita di 14 halaman baru, Kotak Masuk, Pekerjaan, dan Manajemen Label kini punya dua rancangan: kartu putih bertinta gelap dengan tombol utama hitam (terang) dan hitam dengan tombol putih (gelap). Kilau spektrum dilepas dari pita — kilau hanya di ikon header, kartu Sorotan, dan tombol utama saat disorot. Titik \"hari ini\" di judul kecil kini netral (dulu pink).","en":"Bands in the 14 redesigned pages, Inbox, Work and Label Management have two designs: white with dark ink and a black main button (light), black with a white button (dark). Spectral light removed from bands; the \"today\" dot is neutral (was pink)."}},{"id":"dev45-colour","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Semua menu","en":"All menus"}},"title":{"id":"Warna penanda kembali sesuai Kamus Penanda","en":"Indicator colours follow the Indicator Dictionary again"},"detail":{"id":"Titik alur di pita: merah = terlambat, oranye = perlu tindakan (mis. tiket perlu peninjauan, koreksi penarikan, transaksi perlu dicocokkan, hal sebelum produksi), biru = menunggu (dulu semuanya pink). Mode gelap: halaman baru tidak lagi memakai palet lama (merah pink #ff8793, biru/hijau pucat) dan bingkai kaca chip kembali utuh. Dashboard: cincin hitung mundur & langkah siklus biru saat menunggu, oranye saat perlu dibayar/diterbitkan, merah saat terlambat; \"Siap cair\" biru; chip \"Tertinggal\" merah; verifikasi \"Perlu diperiksa\" (dulu \"Menunggu\" oranye); staf menunggu Super Admin = biru; Kondisi menu Tiket/Layanan/Pembaruan: oranye untuk perlu keputusan, merah hanya untuk terlambat.","en":"Band flow dots: red = overdue, orange = action needed, blue = waiting (all were pink). Dark mode no longer leaks the old palette into new pages. Dashboard ring, cycle steps, chips and Menu health use the same meanings."}},{"id":"dev45-align","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard","en":"Dashboard"}},"title":{"id":"Kartu dashboard sejajar di bawah","en":"Dashboard cards line up at the bottom"},"detail":{"id":"\"Perlu keputusan Anda\" dan \"Kondisi menu\" kini sama tinggi dengan kaki daftar menempel di bawah; hal yang sama untuk dashboard Staf (Pekerjaanku · Hasilku/Pengumuman) dan Label.","en":"\"Decisions for you\" and \"Menu health\" now share the same height, as do the Staff and Label dashboard columns."}}]},{"version":"1.1.0-dev.44","date":"2026-10-23","summary":{"id":"Identitas baru: logo RM kaca, header & pita hitam-putih dengan kilau, dan tiga momen suara untuk label.","en":"New identity: glass RM logo, black & white header and bands with spectral light, and three sound moments for labels."},"entries":[{"id":"dev44-logo","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Semua menu","en":"All menus"}},"title":{"id":"Logo baru: RM di balik kaca bening + wordmark \"rilis musik\"","en":"New logo: RM behind clear glass + \"rilis musik\" wordmark"},"detail":{"id":"Ikon RM tebal di balik kaca dengan kilau spektrum di dua sudut, wordmark huruf kecil tebal. Dipakai di header semua peran, ikon tab browser (versi sederhana 16 px), ikon aplikasi, dialog sambutan, dan layar memuat (ikon bernapas). Aset dibuat sekali (±7 KB per tema).","en":"Bold RM behind glass with spectral light on two corners and a lowercase bold wordmark — header, favicon, app icon, welcome dialog and loading screen."}},{"id":"dev44-mono","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Semua menu","en":"All menus"}},"title":{"id":"Header & pita menu hitam-putih dengan kilau","en":"Black & white header and menu bands with spectral light"},"detail":{"id":"Header Dashboard: putih (mode terang) / hitam pekat (mode gelap) dengan kaca berkilau; kartu Sorotan kaca bening bergaris tepi spektrum; tombol utama hitam/putih dengan cincin spektrum saat disorot. Pita di 14 halaman baru, Pekerjaan, dan Manajemen Label menjadi hitam dengan kilau di sudut. Warna status tetap. Desain header bergambar unggahan tetap bisa dipakai (peneduh kini netral).","en":"Dashboard header white/black with glass art; clear Highlight card with spectral edge; bands in every redesigned menu are black with corner light. Status colours unchanged."}},{"id":"dev44-sound","status":"prototype","where":{"role":"label","page":"dashboard","menu":{"id":"Dashboard","en":"Dashboard"}},"title":{"id":"Tiga momen suara untuk label","en":"Three sound moments for labels"},"detail":{"id":"Sambutan pertama setelah akun aktif, rilisan terkirim, dan rilisan tayang: logo beriak mengikuti tanda suara \"da-da-DAAM\" (dibuat di browser, tanpa berkas audio). Efek hanya dimuat saat momen terjadi dan berhenti setelah 1–3 detik; hormati \"kurangi gerakan\". Suara bisa dimatikan di kartu momen atau Profil Label › Suara momen. Staf & Super Admin tidak pernah mendengarnya. Perbaikan: avatar label kini membuka Profil Label (sebelumnya profil staf).","en":"First welcome, release submitted and release live: the logo ripples to a synthesised sonic logo; loaded only at the moment; can be muted. Fix: the label avatar now opens Label Profile."}}]},{"version":"1.1.0-dev.43","date":"2026-10-23","summary":{"id":"Semua halaman baru kini dua bahasa: tombol ID/EN mengganti seluruh teks, tanggal, dan angka.","en":"All redesigned pages are now bilingual: the ID/EN switch changes every text, date and number."},"entries":[{"id":"dev43-i18n-pages","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Semua menu baru","en":"All new menus"}},"title":{"id":"Dua bahasa di 14 halaman baru","en":"Two languages on 14 redesigned pages"},"detail":{"id":"Dashboard, Rilisan, Tiket Bantuan, Layanan Tambahan, Royalti, Penarikan, Transaksi, Pemantauan Keuangan, Kontrak Label, Standar & Penanda, Pembaruan, Kotak Masuk, Staff & Akses, dan Pengaturan Platform kini mengikuti tombol ID/EN: judul, tombol, status, pesan, ringkasan Dashboard, tanggal (\"Friday, 25 Sep 2026 · 09:00\"), dan rupiah (\"Rp 1,162,829\", \"Rp 10M\"). Teks Indonesia tidak berubah. Isi buatan pengguna (nama label, judul lagu, catatan, pesan) tetap seperti ditulis. Naskah kontrak CT-1 tetap bahasa Indonesia sebagai bahasa yang mengikat, dengan catatan dalam bahasa Inggris.","en":"Titles, buttons, statuses, messages, dashboard summaries, dates and rupiah follow the ID/EN switch. User content stays as written; the CT-1 contract body stays in Indonesian (binding language) with an English notice."}},{"id":"dev43-i18n-labels","status":"prototype","where":{"role":"label","page":"dashboard","menu":{"id":"Dashboard","en":"Dashboard"}},"title":{"id":"Label membaca Dashboard dan Pembaruan dalam bahasa Inggris","en":"Labels read the Dashboard and Updates in English"},"detail":{"id":"Butir pembaruan fitur, pengumuman, dan usulan dari rilis tampil dalam bahasa yang dipilih label. Pengingat dari Super Admin ke staf disimpan dua bahasa supaya tampil sesuai bahasa penerima.","en":"Feature updates, announcements and release suggestions show in the label’s language; reminders to staff are stored in both languages."}}]},{"version":"1.1.0-dev.42","date":"2026-10-23","summary":{"id":"Dashboard dirancang ulang untuk Super Admin, Staf, dan Label — semua angka dari menu asalnya.","en":"Dashboard redesigned for Super Admin, Staff and Label — every number comes from its home menu."},"entries":[{"id":"dev42-dashboard-sa","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard","en":"Dashboard"}},"title":{"id":"Dashboard Super Admin: Sorotan, Uang, Perlu keputusan Anda, Kondisi menu, Pertumbuhan","en":"Super Admin dashboard: Highlight, Money, Decisions, Menu health, Growth"},"detail":{"id":"Tanggal sama dengan semua menu. Sorotan memilih keputusan yang ditunggu rekan tim, lalu pekerjaanmu yang terlambat. Uang menampilkan siklus berjalan (pengajuan 1–14, bayar s.d. 20), batang kewajiban ke label, dan empat kotak dari pita Royalti, Penarikan, Pemantauan Keuangan, dan Transaksi; angka contoh lama (Rp 131,6 jt, kas 92 jt) dihapus. Perlu keputusan Anda hanya berisi keputusan Super Admin; tab \"Terlambat di tim\" untuk Tugaskan atau Ingatkan (pengingat masuk Kotak Masuk staf). Kondisi menu memakai kalimat pita biru tiap menu. Pertumbuhan hanya dari data tercatat; bulan tanpa data ditulis \"belum ada data\".","en":"Same date as every menu; Money from the menu bands; only Super Admin decisions; team overdue with assign/remind; menu health from each band; honest growth."}},{"id":"dev42-dashboard-staff","status":"prototype","where":{"role":"admin","page":"dashboard","menu":{"id":"Dashboard","en":"Dashboard"}},"title":{"id":"Dashboard Staf: Berikutnya untukmu, Pekerjaanku, Hasilku, Pengumuman","en":"Staff dashboard: Next for you, My work, My results, Announcements"},"detail":{"id":"Pekerjaan staf dari Rilisan, Tiket Bantuan, Layanan Tambahan, dan Pekerjaan dikelompokkan Terlambat · Hari ini · 7 hari ke depan · Menunggu pihak lain; pekerjaan tanpa petugas bisa langsung diambil. Hasilku (tepat waktu), langkah tercatat hari ini, kehadiran (Catat kehadiran), dan pengumuman internal serta jadwal pemeliharaan. Tanpa angka pendapatan bisnis.","en":"Staff work grouped by time with take-over, on-time rate, today steps, attendance, internal announcements; no business revenue."}},{"id":"dev42-dashboard-label","status":"prototype","where":{"role":"label","page":"dashboard","menu":{"id":"Dashboard","en":"Dashboard"}},"title":{"id":"Dashboard Label: Royalti & penarikan, Kredit, Rilisan, Pesan & layanan, Pembaruan","en":"Label dashboard: Royalty & withdrawals, Credits, Releases, Messages & services, Updates"},"detail":{"id":"Sorotan memilih yang paling perlu dilakukan label (perubahan layanan lama, rilisan yang perlu diperbaiki, kredit yang akan berakhir, penarikan berjalan, data lokasi). Lima kartu hitungan lama dan kartu royalti yang tidak pernah tampil diganti kartu yang langsung bisa ditindaklanjuti. Dashboard kini 2–3 kali lebih ringan saat digambar.","en":"Highlight picks the most needed label action; old count cards replaced with actionable cards; 2–3× lighter to render."}}]},{"version":"1.1.0-dev.41","date":"2026-10-22","summary":{"id":"Pengaturan Platform dirancang ulang dengan pita Kesiapan produksi dan satu versi Paket & Harga.","en":"Platform Settings redesigned with a production-readiness band and one Plans & Prices version."},"entries":[{"id":"dev41-settings-readiness","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Pengaturan Platform","en":"Platform Settings"}},"title":{"id":"Kesiapan produksi: nilai yang belum ditetapkan dihitung di satu pita","en":"Production readiness: undecided values counted in one band"},"detail":{"id":"Pita biru menghitung harga bulanan yang belum ada, harga tahunan yang masih nilai uji, paket kredit yang masih contoh, kontak perusahaan yang kosong (diisi di Kontrak › Penandatangan), menu yang belum diverifikasi, dan website yang belum terbit — dengan \"Isi yang berikutnya\". Prosedur & Pengingat dan Identitas Perusahaan menautkan ke rumah barunya.","en":"The band counts missing monthly prices, test annual prices, sample credit packs, empty company contact, unverified menus and the unpublished website."}},{"id":"dev41-settings-plans","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Pengaturan Platform","en":"Platform Settings"}},"title":{"id":"Paket & Harga: satu versi untuk paket, isi paket, harga layanan, dan paket kredit","en":"Plans & Prices: one version for plans, inclusions, service prices and credit packs"},"detail":{"id":"Harga tahunan/bulanan, layanan yang termasuk paket (Konten Promosi, Smart Link, Video Visualizer, Registrasi WAMI), harga layanan, harga 1 kredit, dan paket kredit diubah di satu tempat lalu terbit sebagai versi baru yang berlaku untuk pembelian baru. Kredit dipakai untuk rilisan (Standard · Express · MAX) setara harga rupiahnya; layanan tambahan dibayar rupiah atau benefit paket. Istilah token dan \"vonis\" tidak dipakai.","en":"Plan prices, inclusions, service prices, credit price and packs change in one place and publish as a new version for new purchases."}},{"id":"dev41-settings-other","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Pengaturan Platform","en":"Platform Settings"}},"title":{"id":"Website, Pemeliharaan, Navigasi, Tampilan, dan Riwayat aktivitas","en":"Website, Maintenance, Navigation, Appearance and Activity"},"detail":{"id":"Website (hero, pratinjau dengan harga & kontak otomatis, FAQ) kini bisa diterbitkan. Pemeliharaan: jadwal baru langsung membuat draf pengumuman di Pembaruan; jadwal bisa dibatalkan. Navigasi membaca menu sebenarnya per jenis akun; urutan dan sembunyikan menu Super Admin tersimpan sebagai versi; tandai diverifikasi. Tampilan membuka editor kartu header lengkap. Riwayat aktivitas dengan saringan menu, pencarian, dan unduh CSV. Perbaikan: tautan pemeliharaan dari Pembaruan tidak lagi tertimpa jeda header.","en":"Publishable website, maintenance with announcement drafts, real menu order/visibility with versions, appearance editor link, and a filterable activity log with CSV."}}]},{"version":"1.1.0-dev.40","date":"2026-10-22","summary":{"id":"Staff & Akses dirancang ulang: orang, pekerjaannya, dan izinnya dalam satu halaman.","en":"Staff & Access redesigned: people, their work and their permissions on one page."},"entries":[{"id":"dev40-staff-team","status":"prototype","where":{"role":"super","page":"access","menu":{"id":"Staff & Akses","en":"Staff & Access"}},"title":{"id":"Tim: akses, pekerjaan aktif, kinerja, kehadiran, dan riwayat per orang","en":"Team: access, active work, performance, attendance and history per person"},"detail":{"id":"Pita \"Tim hari ini\" menghitung orang aktif, pekerjaan berjalan, kehadiran staf, peran yang belum ditinjau, dan izin sensitif. Rincian orang: Ubah akses (peran & cakupan label) dengan dampak dan pengalihan pekerjaan yang keluar dari cakupan, Pekerjaan aktif dari semua menu, cincin tepat waktu bulan berjalan, kehadiran hari ini, riwayat akses, Pratinjau akses, Undang staf, dan Nonaktifkan dengan pengalihan pekerjaan per orang + alasan (bukan akun sendiri, bukan Super Admin terakhir). Semua lewat fungsi akses yang asli.","en":"Team band and person detail with change access (impact + handover), active work, on-time ring, attendance, history, preview, invite and deactivate with per-job handover."}},{"id":"dev40-staff-roles","status":"prototype","where":{"role":"super","page":"access","menu":{"id":"Staff & Akses","en":"Staff & Access"}},"title":{"id":"Peran & Izin: matriks Lihat · Kerjakan · Putuskan, izin sensitif, tandai ditinjau","en":"Roles: View · Do · Decide matrix, sensitive permissions, mark reviewed"},"detail":{"id":"Super Admin peran tetap; peran staf diatur lewat matriks per menu baru (keputusan khusus Super Admin terkunci 🔒), rincian izin satu per satu, dan sakelar izin sensitif (Lihat rekening lengkap, Ekspor data) yang wajib beralasan saat dinyalakan. Perubahan yang membuat pekerjaan tidak bisa ditangani lagi meminta pengganti. Peran yang berubah tampil \"Belum ditinjau\" sampai ditandai sudah ditinjau.","en":"Fixed Super Admin role; staff role matrix with locked Super Admin decisions, sensitive toggles needing a reason, handover on impact, and review marking."}},{"id":"dev40-staff-fixes","status":"prototype","where":{"role":"super","page":"access","menu":{"id":"Staff & Akses","en":"Staff & Access"}},"title":{"id":"Perbaikan: tidak bisa menonaktifkan diri sendiri, judul tiket, hitung ganda, istilah","en":"Fixes: no self-deactivation, ticket titles, double counting, wording"},"detail":{"id":"Super Admin tidak lagi bisa menonaktifkan akunnya sendiri. Judul pekerjaan tiket tidak lagi \"undefined\". Pekerjaan T-318 yang sudah menjadi tiket tidak dihitung dua kali. Kartu \"Tim hari ini\" di Dashboard menyebut Super Admin, bukan istilah lama.","en":"Super Admins can no longer deactivate themselves; ticket job titles fixed; migrated T-318 no longer double counted; dashboard team card says Super Admin."}}]},{"version":"1.1.0-dev.39","date":"2026-10-22","summary":{"id":"Kotak Masuk menjadi aliran \"untukmu\" dan semua percakapan label menjadi tiket.","en":"The Inbox becomes a \"for you\" stream and every label conversation becomes a ticket."},"entries":[{"id":"dev39-inbox-stream","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Kotak Masuk","en":"Inbox"}},"title":{"id":"Satu aliran \"untukmu\": Perlu jawaban · Disebut & ditugaskan · Notifikasi","en":"One \"for you\" stream: Needs reply · Mentions & assignments · Notifications"},"detail":{"id":"Hanya yang menunggumu: tiket yang pesan terakhirnya dari label, eskalasi dan penyelesaian layanan yang perlu keputusan Super Admin, penugasan, sebutan @nama, dan notifikasi — dibagi Belum/Sudah dibaca. Tiket selesai tidak lagi memenuhi daftar. Balasan dan catatan internal tersimpan di tiketnya; keputusan diambil di menu asal lewat \"Buka & putuskan\". Notifikasi hilang sendiri saat pekerjaannya selesai. Halaman tanpa sidebar. Tab Berita sudah pindah ke Pembaruan › Pengumuman.","en":"Only what waits for you, split read/unread; replies and notes are saved on the ticket; decisions stay in their menus; notifications clear themselves."}},{"id":"dev39-inbox-tickets","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Kotak Masuk","en":"Inbox"}},"title":{"id":"Satu sistem percakapan: obrolan lama menjadi tiket","en":"One conversation system: old chats become tickets"},"detail":{"id":"Percakapan T-318, T-322, T-325, dan pengajuan pengembalian Kopi Senja (TKT-0901) kini tiket \"Permintaan lainnya\" (TKT-0036–0039) lengkap dengan pesan, catatan internal, petugas, dan statusnya. Sebelumnya balasan tim di obrolan lama tidak pernah sampai ke label; kini label membacanya di Pesan. Pengajuan RF-1 menunjuk ke tiket barunya.","en":"Old chats T-318/T-322/T-325 and the TKT-0901 refund chat become tickets so replies reach labels in Messages."}},{"id":"dev39-inbox-header","status":"prototype","where":{"role":"super","page":"dashboard"},"title":{"id":"Satu pintu di header","en":"One door in the header"},"detail":{"id":"Lonceng dan chat simulasi dilebur ke ikon Kotak Masuk dengan satu angka belum dibaca.","en":"The bell and simulated chat merge into the Inbox icon with one unread count."}}]},{"version":"1.1.0-dev.38","date":"2026-10-22","summary":{"id":"Pembaruan menjadi tempat berbicara ke label: butir fitur yang dikelola dan pengumuman yang bisa dijadwalkan.","en":"Updates becomes the place to talk to labels: managed feature notes and schedulable announcements."},"entries":[{"id":"dev38-updates-features","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Pembaruan","en":"Updates"}},"title":{"id":"Butir pembaruan fitur dikelola: draf, ditahan, terbit, ditarik","en":"Managed feature notes: draft, held, published, withdrawn"},"detail":{"id":"18 butir panduan lama kini data yang dikelola Super Admin dengan istilah yang dirapikan (kredit; Basic · Studio · Pro · Business), audiens Semua label / Tim internal / Label paket lama, dan Pratinjau sebagai label. Kalimat tarif 60% ditahan sampai bunyinya ditetapkan. \"Di balik layar\" hanya untuk tim internal. Setiap dev release menjadi usulan: jadikan draf untuk label atau catat untuk tim internal.","en":"The 18 old guide items become managed notes with audiences and a label preview; the rate sentence is held; each dev release becomes a suggestion."}},{"id":"dev38-updates-announcements","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Pembaruan","en":"Updates"}},"title":{"id":"Pengumuman pindah dari Kotak Masuk › Berita","en":"Announcements move from Inbox › News"},"detail":{"id":"Tulis pengumuman sebagai draf, terbitkan sekarang atau jadwalkan, pilih audiens, dan jadikan wajib baca. Daftar penerima menunjukkan siapa yang sudah membaca, dengan tombol Ingatkan. Jadwal pemeliharaan ikut tampil. Draf dan jadwal yang belum tiba tidak sampai ke label.","en":"Draft, publish or schedule announcements with audiences and must-read tracking plus reminders; maintenance windows are listed."}},{"id":"dev38-updates-label","status":"prototype","where":{"role":"label","page":"module","menu":{"id":"Pembaruan","en":"Updates"}},"title":{"id":"Halaman Pembaruan label membaca butir yang sama","en":"The label Updates page reads the same notes"},"detail":{"id":"Label melihat pengumuman dan butir yang terbit untuknya, dikelompokkan per topik, dengan tanda \"Baru\" sejak kunjungan terakhir. Butir internal, draf, usulan, dan kalimat yang ditahan tidak terlihat.","en":"Labels see the announcements and published notes meant for them, grouped by topic with \"New\" markers."}}]},{"version":"1.1.0-dev.37","date":"2026-10-22","summary":{"id":"Standar & Penanda menjadi buku aturan: kamus status, aturan waktu, syarat lencana, standar layanan, dan riwayat versi.","en":"Standards & Indicators becomes the rulebook: status dictionary, timing rules, badge requirements, service standards and version history."},"entries":[{"id":"dev37-standards-kamus","status":"prototype","where":{"role":"super","page":"standards9","menu":{"id":"Standar & Penanda","en":"Standards & Indicators"}},"title":{"id":"Kamus status semua menu dengan jumlah dari data asli","en":"Status dictionary for every menu with live counts"},"detail":{"id":"61 status dari Pekerjaan, Rilisan, Penarikan, Akses & Aktivitas label, Royalti, WAMI, Layanan Tambahan, Tiket Bantuan, dan Transaksi dalam satu kamus: arti, kapan muncul dan hilang, warna, urutan, dan \"Lihat N di menu\". Jumlahnya dihitung dari data menu masing-masing (tidak lagi salinan teks yang bisa berbeda). Pita biru menampilkan status merah/oranye yang paling banyak.","en":"One dictionary of 61 statuses with meaning, when they appear/clear, colour, order and live counts from each menu."}},{"id":"dev37-standards-rules","status":"prototype","where":{"role":"super","page":"standards9","menu":{"id":"Standar & Penanda","en":"Standards & Indicators"}},"title":{"id":"Aturan waktu pindah ke sini dan terbit sebagai versi baru","en":"Timing rules move here and publish as new versions"},"detail":{"id":"Prosedur & Pengingat (11 tenggat tahap, 6 aturan tindak lanjut, kalender operasional) kini diubah dari Standar & Penanda. Setiap perubahan menampilkan dampak nyata ke pekerjaan berjalan (berapa yang tenggatnya berubah atau menjadi terlambat) lalu terbit sebagai versi berikutnya lewat fungsi Prosedur yang asli. Aturan tindak lanjut bernilai contoh bisa ditandai sudah diverifikasi. Staf membaca tanpa tombol ubah.","en":"Procedures & reminders now edit here with real impact on ongoing work and publish as the next version; staff read only."}},{"id":"dev37-standards-badges","status":"prototype","where":{"role":"super","page":"standards9","menu":{"id":"Standar & Penanda","en":"Standards & Indicators"}},"title":{"id":"Syarat lencana dengan pratinjau siapa mendapat atau kehilangan centang","en":"Badge requirements with a gain/lose preview"},"detail":{"id":"Ambang Verifikasi Label dan Master Multi-label diubah dengan tombol −/+; sebelum terbit tampil nama label yang akan mendapat atau kehilangan centang (pencapaian lama dipertahankan). Standar layanan (Layanan tambahan, Tiket bantuan, Transaksi, WAMI) dan Riwayat versi sungguhan melengkapi halaman. Panduan desain internal tidak lagi tampil di aplikasi.","en":"Badge thresholds with a named gain/lose preview; service standards and real version history; internal design guides leave the app."}},{"id":"dev37-role-repaint","status":"prototype","where":{"role":"super","page":"module"},"title":{"id":"Perbaikan: ganti peran di Studio langsung memperbarui tombol","en":"Fix: switching roles in Studio refreshes the buttons immediately"},"detail":{"id":"Rilisan, Tiket Bantuan, Layanan Tambahan, Royalti, dan Penarikan kini menggambar ulang saat peran berganti, sehingga tombol khusus Super Admin tidak tersisa di tampilan Staf.","en":"Pages now repaint on role switch so Super Admin-only buttons do not linger for staff."}}]},{"version":"1.1.0-dev.36","date":"2026-10-22","summary":{"id":"Kontrak Label: status per label, naskah CT-1 16 pasal, dan penandatangan dalam satu halaman.","en":"Label Contracts: per-label status, the 16-article CT-1 text and the company signer on one page."},"entries":[{"id":"dev36-contracts-status","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Kontrak Label","en":"Label Contracts"}},"title":{"id":"Status kontrak per label: Berlaku · Belum disetujui · Diakhiri","en":"Per-label contract status: Active · Not accepted · Ended"},"detail":{"id":"Kartu \"Persetujuan label\" yang hilang sejak v10.7 kembali sebagai tab Status kontrak: 21 label berlaku dengan CT-1, 4 calon member belum menyetujui. Rincian berisi versi yang disetujui, bukti persetujuan (waktu, cara, versi identitas), tarif royalti yang tercatat di akun, riwayat, Ingatkan (notifikasi ke label), Unduh salinan persetujuan, dan Akhiri kontrak dengan alasan (pengiriman rilisan baru langsung tertahan; bisa dibatalkan). Kontrak berlaku selama akun aktif, tanpa tanggal berakhir.","en":"The label consent list returns as a status tab with proof of consent, reminders, a consent copy download and termination with a reason."}},{"id":"dev36-contracts-text","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Kontrak Label","en":"Label Contracts"}},"title":{"id":"Naskah CT-1 16 pasal; Pasal 8 diisi Super Admin","en":"16-article CT-1 text; article 8 filled in by the Super Admin"},"detail":{"id":"Naskah lama 3 kalimat diganti Perjanjian Distribusi Musik 16 pasal (draf, perlu tinjauan hukum sebelum produksi) dengan daftar pasal, pokok isi, dan unduh naskah. Label membaca naskah yang sama di aplikasinya. Pasal 8 (royalti) ditulis Super Admin lewat tombol Isi Pasal 8. Tombol \"Buat revisi kontrak\" dihapus.","en":"The old 3-sentence text is replaced by the 16-article agreement; labels read the same text; article 8 is written by the Super Admin; the revision button is removed."}},{"id":"dev36-contracts-signer","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Kontrak Label","en":"Label Contracts"}},"title":{"id":"Penandatangan: badan hukum, penanggung jawab, tanda tangan & stempel","en":"Signer: legal entity, signatory, signature & stamp"},"detail":{"id":"Satu sumber identitas untuk dokumen hukum: nama badan hukum, kedudukan, alamat, NIB, kontak, penanggung jawab dan jabatan, serta unggah tanda tangan & stempel (diperkecil otomatis, hanya Super Admin). Isiannya langsung dipakai di Pasal 1 naskah dan blok tanda tangan. Yang belum diisi tampil \"belum diisi\" — identitas perusahaan masih menunggu keputusan.","en":"One identity source for legal documents, used in article 1 and the signature block; empty fields show \"not filled in\" pending the company identity decision."}}]},{"version":"1.1.0-dev.35","date":"2026-10-22","summary":{"id":"Pemantauan Keuangan menjadi satu halaman \"Posisi keuangan\" di atas data asli; saldo lama tidak minus lagi.","en":"Finance Monitor becomes a single \"Financial position\" page on real data; legacy balances are no longer negative."},"entries":[{"id":"dev35-finance-position","status":"prototype","where":{"role":"super","page":"liability9","menu":{"id":"Pemantauan Keuangan","en":"Finance Monitor"}},"title":{"id":"Posisi keuangan: kas − kewajiban ke label = cadangan","en":"Financial position: cash − label liabilities = reserve"},"detail":{"id":"Tampilan persis mock yang disetujui: pita biru dengan status Aman / Perlu perhatian / Kas tidak cukup, empat blok (Kas & rekonsiliasi, Kewajiban ke label, Akan masuk, Pendapatan layanan) yang menautkan ke Royalti, Penarikan, dan Transaksi, serta kalender kas rekening royalti sampai akhir bulan pencairan dengan dua skenario (dana Believe masuk, semua label siap ikut menarik). Angka dari sumber yang sama dengan menu asalnya: kewajiban ke label Rp 41.992.053 (tersedia + sedang dicairkan), 6 label siap cair Rp 29.894.879, laporan Believe Juni & September yang belum menerima dana.","en":"Matches the approved mock: status band, four linked blocks and a cash calendar with two scenarios, all from the same sources as their home menus."}},{"id":"dev35-finance-cash","status":"prototype","where":{"role":"super","page":"liability9","menu":{"id":"Pemantauan Keuangan","en":"Finance Monitor"}},"title":{"id":"Rekonsiliasi kas per rekening, selisih wajib dijelaskan","en":"Per-account cash reconciliation with mandatory difference notes"},"detail":{"id":"Rekening royalti (dana Believe masuk, pencairan keluar) dan rekening operasional (pembayaran layanan masuk, pengembalian keluar). Saldo seharusnya dihitung dari catatan kas terakhir + mutasi buku; saat mencatat saldo dari mutasi bank, selisih tampil langsung dan wajib dijelaskan. Lampiran mutasi dicatat namanya. Catatan memakai fungsi kas yang asli (hanya Super Admin). Belum ada saldo contoh: halaman jujur menampilkan \"Kas belum dicatat\" sampai catatan pertama dibuat.","en":"Royalty and operational accounts; expected balance from the last record plus book movements; differences must be explained; uses the real cash function (Super Admin only)."}},{"id":"dev35-finance-moved","status":"prototype","where":{"role":"super","page":"liability9","menu":{"id":"Pemantauan Keuangan","en":"Finance Monitor"}},"title":{"id":"Tab lama dipindah; perbaikan saldo minus","en":"Old tabs moved; negative balance fix"},"detail":{"id":"Pemantauan Dana & Kewajiban Royalti → Royalti › Saldo label, Perkembangan Katalog → Royalti › Analitik (tautan langsung membuka tabnya), Kredit & Tarif Khusus → Manajemen Label. Bonus Kredit sementara tetap membuka alat lama sampai pindah ke Manajemen Label. Perbaikan: saldo awal label lama tidak lagi minus (Nusantara −Rp 6,6 jt, Rimba, Tepian) karena pengajuan terbuka tidak dikurangkan dua kali.","en":"Old tabs now live in Royalty and Label Management (bonus credits keep the old tool for now). Fix: legacy opening balances are no longer negative."}}]},{"version":"1.1.0-dev.34","date":"2026-10-22","summary":{"id":"Transaksi dirancang ulang di atas data asli, termasuk antrean pengembalian paket lama.","en":"Transactions redesigned on real data, including the legacy-plan refund queue."},"entries":[{"id":"dev34-transactions-redesign","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Transaksi","en":"Transactions"}},"title":{"id":"Transaksi baru: Transaksi · Pengembalian, satu langkah per kasus","en":"New Transactions: Transactions · Refunds, one step per case"},"detail":{"id":"Tampilan persis mock yang disetujui: pita biru hanya menghitung yang perlu ditangani (Belum dipenuhi · Tidak cocok penyedia · Dana tanpa transaksi · Menunggu info label · Pengembalian berjalan), pil jenis Paket · Kredit · Layanan, satu status per transaksi, tabel Rilis Musik vs penyedia, dan langkah berikutnya di panel kanan: Penuhi pembelian, Terima pembayaran penyedia, Perbarui & penuhi, Buka pengembalian, Hubungkan dana tanpa transaksi. Pita \"Pratinjau V11.3\", Panduan, dan tombol simulasi pengembang tidak tampil lagi. Semua tombol memakai fungsi transaksi yang asli.","en":"Matches the approved mock: a blue band counting only what needs handling, kind pills, one status per transaction, a Rilis Musik vs provider table and one next step per case, all on the real transaction functions."}},{"id":"dev34-transactions-refunds","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Transaksi","en":"Transactions"}},"title":{"id":"Pengembalian: paket lama dan transaksi dalam satu antrean","en":"Refunds: legacy plans and transactions in one queue"},"detail":{"id":"Pengembalian paket lama (Annual/VIP) mengikuti keputusan 19 Okt: refund penuh, batas 30 hari sejak pemberitahuan dibaca, hanya Super Admin yang memutuskan, nomor referensi wajib saat dibayar, lalu label pindah ke Basic. Label yang berhak tetapi belum mengajukan ikut terlihat beserta paparannya. Pengembalian transaksi: nominal (maks sisa dana), jalur asal atau transfer ke rekening yang dikonfirmasi label, hasil pemeriksaan wajib, dan Catat dibayar dengan referensi. Keputusan di Dashboard dan notifikasi RF-… kini membuka halaman ini.","en":"Legacy refunds follow the 19 Oct decision (full refund, 30 days from reading, Super Admin only, reference required, then Basic); eligible labels are listed. Transaction refunds: amount, route, mandatory review result and reference. Dashboard decisions and RF notifications open this page."}},{"id":"dev34-transactions-fixes","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Transaksi","en":"Transactions"}},"title":{"id":"Perbaikan: pengajuan paket lama contoh tidak lagi yatim","en":"Fix: the sample legacy refund request is no longer orphaned"},"detail":{"id":"Label contoh memakai id baru (mis. kopi-senja-records) dengan kode lama S01/S02, sehingga pengajuan RF-1 Kopi Senja Records tidak muncul di antrean keputusan dan pembayaran refund tidak memindahkan label ke Basic. Kode lama kini dicocokkan lewat source9. Ditambahkan juga: menerima pembayaran penyedia yang lebih besar dari harga (selisih otomatis jadi pengembalian), menutup kasus \"informasi diminta\" bila tidak ada pembayaran, dan penyelesaian dana tanpa transaksi (hubungkan, kembalikan ke pengirim, tandai ditangani).","en":"Sample labels use new ids with legacy codes S01/S02, which orphaned RF-1; legacy codes now match via source9. Also added: accept a larger provider amount (difference becomes a refund), close info cases with no payment, and resolve unmatched funds."}}]},{"version":"1.1.0-dev.33","date":"2026-10-22","summary":{"id":"Penarikan dirancang ulang di atas data asli; pengajuan contoh tidak lagi terblokir rekening.","en":"Withdrawals redesigned on real data; sample requests no longer blocked by bank checks."},"entries":[{"id":"dev33-withdraw-redesign","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Penarikan","en":"Withdrawals"}},"title":{"id":"Penarikan baru: Dalam proses · Riwayat, siklus 1–14 / bayar s.d. 20","en":"New Withdrawals: In progress · History, the 1–14 / pay-by-20 cycle"},"detail":{"id":"Tampilan persis mock yang disetujui: pita siklus Menunggu pemeriksaan → Siap dibayar → Sedang ditransfer → Ditunda → Koreksi (41 kartu lama hilang), 6 pemeriksaan sebelum menyetujui, data salin untuk transfer hanya di Siap dibayar, hasil transfer Berhasil (nomor referensi bank wajib) / Belum pasti / Gagal, Tunda dengan alasan, Pakai rekening terbaru, Koreksi pembayaran, dan Unduh daftar transfer (CSV). Semua tombol memakai fungsi penarikan yang asli.","en":"Matches the approved mock with checks, copy-ready transfer data, transfer results with mandatory bank reference, delays, corrections and a transfer list CSV."}},{"id":"dev33-withdraw-cycle","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Penarikan","en":"Withdrawals"}},"title":{"id":"Pengajuan di luar tanggal 1–14 ikut siklus berikutnya","en":"Requests outside the 1st–14th roll into the next cycle"},"detail":{"id":"Pengajuan 25 Sep (WD-0039–0041) kini bertenggat 20 Okt, bukan \"lewat tenggat\". Keterangan transfer baru ROYALTI OKT 2026 WD-xxxx; pembayaran lama tetap dengan keterangan yang tercatat. Nama bank (BCA, BRI, BNI, BSI) dan kota dirapikan di tampilan.","en":"Late requests now fall due on the 20th of the next month; new transfer memo; bank and city names tidied."}},{"id":"dev33-withdraw-bankfix","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Penarikan","en":"Withdrawals"}},"title":{"id":"Perbaikan: rekening yang sama tidak lagi dianggap berubah","en":"Fix: the same bank account is no longer treated as changed"},"detail":{"id":"Rekening pada pengajuan dibandingkan menurut bank, nomor, dan penerima — bukan seluruh catatan (yang memuat versi & status) — sehingga tiga pengajuan contoh bisa disetujui dan dibayar.","en":"Bank accounts are compared by bank, number and holder, so the three sample requests can be approved and paid."}}]},{"version":"1.1.0-dev.32","date":"2026-10-22","summary":{"id":"Royalti dirancang ulang di atas data asli (Laporan · Saldo label · Analitik); saldo awal migrasi bukan pendapatan; saldo ganda diperbaiki.","en":"Royalties redesigned on real data; migration opening balance no longer counted as income; double-counted balances fixed."},"entries":[{"id":"dev32-royalty-reports","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Royalti","en":"Royalties"}},"title":{"id":"Tab Laporan: siklus laporan Believe","en":"Reports tab: the Believe report cycle"},"detail":{"id":"Laporan & Impor yang dulu tersembunyi kini tab pertama. Pita biru Perlu diperiksa → Siap diterbitkan → Menunggu dana → Selesai, dengan tanda \"tertinggal\" (Juni 2026 belum terbit padahal Juli–Agustus sudah). Satu tombol utama per tahap: Terbitkan ke N label, lalu Catat dana diterima. Pemeriksaan otomatis menggantikan Audit Konsistensi. Impor, pencocokan baris, koreksi, dan ganti file memakai layar impor yang sudah ada.","en":"The hidden Imports module becomes the first tab with the report cycle, a lagging-period warning, Publish and Record funds received."}},{"id":"dev32-royalty-balances","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Royalti","en":"Royalties"}},"title":{"id":"Tab Saldo label: Kirim pengingat & Sesuaikan saldo","en":"Label balances tab: reminders & balance adjustments"},"detail":{"id":"Saldo per akun pencairan (tersedia, menunggu dana, sedang dicairkan, sudah dibayar) dengan buku masuk/keluar. Kirim pengingat masuk ke notifikasi label (\"Saldo royaltimu sudah bisa dicairkan\"). Sesuaikan saldo (Super Admin) wajib alasan, tercatat di buku saldo dan riwayat, dan tidak boleh membuat saldo minus.","en":"Balances per payout account with in/out ledger, label reminders, and Super Admin adjustments with a mandatory reason."}},{"id":"dev32-royalty-analytics","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Royalti","en":"Royalties"}},"title":{"id":"Tab Analitik: per periode, platform, label, dan lagu","en":"Analytics tab: by period, platform, label and track"},"detail":{"id":"Hanya laporan yang sudah terbit. Pencarian lagu/artis/label menggantikan Pendapatan Artis. Saldo awal migrasi (Rp 1,63 M) tidak lagi dihitung sebagai pendapatan Juli — di analitik, laporan label, maupun Pemantauan.","en":"Published reports only; artist search replaces Artist Revenue; the migration opening balance is excluded everywhere."}},{"id":"dev32-money-fixes","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Royalti","en":"Royalties"}},"title":{"id":"Perbaikan angka uang","en":"Money number fixes"},"detail":{"id":"Saldo tersedia tiga label (Nusantara Records, Tepian Musik, Rimba Musik) tidak lagi dihitung dua kali dengan pengajuan penarikannya. Waktu impor & dana memakai jam prototipe, bukan jam komputer. Tombol di halaman Penarikan lama yang selalu gagal (\"reconcilePayoutAchievements116\") diperbaiki. Muat ulang data contoh untuk melihat angka baru.","en":"Three balances were double-counted; import times used the computer clock; the old Withdrawals buttons always failed. Reload sample data to see the new numbers."}}]},{"version":"1.1.0-dev.31","date":"2026-10-22","summary":{"id":"Layanan Tambahan dirancang ulang di atas data asli; Registrasi WAMI bergabung ke dalamnya.","en":"Add-on Services redesigned on real data; WAMI Registration merged in."},"entries":[{"id":"dev31-addons-redesign","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Layanan Tambahan","en":"Add-on Services"}},"title":{"id":"Layanan Tambahan baru: Dalam proses · Selesai, rincian di samping","en":"New Add-on Services: In progress · Done, details beside the list"},"detail":{"id":"Tampilan persis mock yang disetujui: pita alur Perlu diperiksa → Menunggu bahan → Sedang dikerjakan → Menunggu tanggapan → Penyelesaian, pil per layanan + WAMI, dan satu langkah berikutnya per tahap: Mulai pengerjaan (menjadikanmu petugas), Minta kelengkapan, Catat kendala, simpan draf (tautan https), Kirim ke label, tinjau revisi (jatah / kesalahan petugas / di luar cakupan), dan Penyelesaian oleh Super Admin (usulan pengembalian atau jadwal baru; uang diproses di Transaksi). Semua tombol memakai fungsi layanan yang asli.","en":"Matches the approved mock; every action uses the original add-on model, so Transactions, packages and labels update too."}},{"id":"dev31-wami-merge","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Layanan Tambahan","en":"Add-on Services"}},"title":{"id":"Registrasi WAMI pindah ke Layanan Tambahan","en":"WAMI Registration moves into Add-on Services"},"detail":{"id":"Menu Registrasi WAMI tidak lagi di sidebar Super Admin & Staf (label tetap bisa mengajukan). Pengajuan satu rilisan tampil satu baris berisi lagu-lagunya: periksa per lagu → Siap didaftarkan → dua langkah pengiriman → catat nomor WAMI per lagu, plus tindak lanjut ke WAMI. Tenggat mengikuti aturan WAMI di Pengaturan › Prosedur.","en":"The WAMI item leaves the staff sidebar; one submission shows as one row with its songs, with per-song WAMI numbers."}},{"id":"dev31-addons-entry","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Layanan Tambahan","en":"Add-on Services"}},"title":{"id":"Pintu masuk yang sama untuk pesanan & WAMI","en":"Consistent entry points for orders & WAMI"},"detail":{"id":"Membuka pesanan atau pendaftaran WAMI dari Pekerjaan, notifikasi, Transaksi, atau Studio kini membuka halaman baru di item yang sama.","en":"Opening an order or WAMI registration from Work, notifications, Transactions or Studio lands on the new page."}}]},{"version":"1.1.0-dev.30","date":"2026-10-22","summary":{"id":"Tiket Bantuan dirancang ulang dan tersambung ke data asli; pengajuan ganda digabung.","en":"Support Tickets redesigned on real data; duplicate requests merged."},"entries":[{"id":"dev30-tickets-redesign","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Tiket Bantuan","en":"Support Tickets"}},"title":{"id":"Tiket Bantuan baru: Dalam proses · Selesai, rincian di samping","en":"New Support Tickets: In progress · Done, details beside the list"},"detail":{"id":"Tampilan persis mock yang disetujui: pita alur Baru → Ditangani → Menunggu label → Menunggu distributor → Perlu peninjauan, tiga kelompok kategori (Rilisan · YouTube & Content ID · Lainnya), dan rincian dengan satu langkah berikutnya per tahap: Mulai penanganan, Teruskan ke distributor (dengan nomor referensi), hasil per bagian, tindak lanjut, Tandai selesai, eskalasi & peninjauan Super Admin, Alihkan. Balas ke label dan Catatan internal ada di percakapan. Semua tombol memakai fungsi tiket asli, jadi Pesan label, Kotak Masuk, dan rilisan terkait ikut berubah.","en":"Matches the approved mock. Every action uses the original ticket model, so the label chat, Inbox and linked releases update too."}},{"id":"dev30-tickets-duplicates","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Tiket Bantuan","en":"Support Tickets"}},"title":{"id":"35 tiket penurunan ganda tampil sebagai 3 baris","en":"35 duplicate takedown tickets shown as 3 rows"},"detail":{"id":"Tiket selesai untuk rilisan & kategori yang sama digabung di tampilan (\"28 pengajuan digabung\"), datanya tidak diubah. Riwayat rilisan yang berulang (mis. 28 hasil penurunan yang sama) kini satu baris \"×N\".","en":"Done tickets for the same release and category are grouped in the view; data is unchanged. Repeated release history lines collapse into one \"×N\" line."}},{"id":"dev30-tickets-flow","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Tiket Bantuan","en":"Support Tickets"}},"title":{"id":"Tenggat tiket & pintu masuk yang sama","en":"Ticket deadlines & consistent entry points"},"detail":{"id":"Tiket baru jatuh tempo menurut Respons awal tiket (1 hari kerja), tiket di distributor menurut jadwal tindak lanjut dari Pengaturan › Prosedur. Membuka tiket dari Pekerjaan, Kotak Masuk, atau Studio kini membuka halaman baru di tiket yang sama.","en":"New tickets follow the first-response rule; tickets at the distributor follow the follow-up schedule. Opening a ticket from Work, Inbox or Studio lands on the new page."}},{"id":"dev30-maint-banner","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Tiket Bantuan","en":"Support Tickets"}},"title":{"id":"Banner pemeliharaan rapi di halaman baru","en":"Maintenance banner fits the new pages"},"detail":{"id":"Saat ada jadwal pemeliharaan, banner kini tampil di atas isi halaman Rilisan dan Tiket Bantuan (sebelumnya mendorong sidebar ke tengah).","en":"During maintenance the banner now sits above the new pages instead of pushing the sidebar."}}]},{"version":"1.1.0-dev.29","date":"2026-10-22","summary":{"id":"Rilisan dirancang ulang dan tersambung ke data asli; Adovi dihapus, tim = Jeck Rotama, Eka Poetra, Cantika Dewi.","en":"Releases redesigned on real data; Adovi removed, team = Jeck Rotama, Eka Poetra, Cantika Dewi."},"entries":[{"id":"dev29-releases-redesign","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Rilisan","en":"Releases"}},"title":{"id":"Rilisan baru: Dalam proses · Katalog, rincian di samping","en":"New Releases: In progress · Catalogue, details beside the list"},"detail":{"id":"Tampilan persis mock yang disetujui: pita alur 6 tahap (klik untuk menyaring), daftar per tahap, dan rincian di samping dengan satu langkah berikutnya per tahap (Mulai pemeriksaan, centang 5 butir, Setujui, Kirim ke Believe, kode UPC/ISRC, hasil di toko, Tolak). Semua tombol memakai fungsi rilisan yang asli, jadi label, Pekerjaan, dan notifikasi ikut berubah. Rencana & Kampanye tidak tampil untuk Super Admin.","en":"Matches the approved mock: a 6-stage flow band, a list per stage and a side panel with one next step per stage. Every button uses the original release actions, so labels, Work and notifications update too."}},{"id":"dev29-releases-deadlines","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Rilisan","en":"Releases"}},"title":{"id":"Tenggat dari Aturan waktu, sama di Pekerjaan & Dashboard","en":"Deadlines from the timing rules, shared with Work & Dashboard"},"detail":{"id":"Tenggat dihitung dari Pengaturan › Prosedur: pemeriksaan 2 hari kerja, pengiriman 1, pemeriksaan Believe 3, perbaikan label 24 jam, mengikuti kalender kerja & libur. Pekerjaan dan Dashboard kini memakai tenggat yang sama (sebelumnya tanggal rilis), dan rilisan yang diturunkan tidak lagi muncul sebagai pekerjaan terlambat.","en":"Deadlines follow Settings › Procedures (review 2 working days, delivery 1, Believe check 3, label fixes 24 h). Work and Dashboard now use the same deadlines, and taken-down releases no longer show as overdue work."}},{"id":"dev29-releases-fixes","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Rilisan","en":"Releases"}},"title":{"id":"Perbaikan: Tolak pada rilisan diturunkan, petugas dari Pekerjaan","en":"Fixes: reject on taken-down releases, assignee from Work"},"detail":{"id":"Tombol Tolak (staf) dan Batalkan (label) tidak lagi muncul untuk rilisan Diturunkan atau sebagian tayang. Ambil/Tugaskan di Pekerjaan kini tersimpan sebagai petugas rilisan dan tercatat di riwayat. Tanggal di judul Pekerjaan sama dengan menu lain.","en":"Reject (staff) and Cancel (label) no longer appear for taken-down or partially live releases. Take/Assign in Work now persists as the release assignee and is logged."}},{"id":"dev29-team","status":"prototype","where":{"role":"super","page":"dashboard"},"title":{"id":"Tim: Adovi dihapus dari semua data","en":"Team: Adovi removed from all data"},"detail":{"id":"Tim prototipe kini 2 Super Admin (Jeck Rotama, Eka Poetra) dan 1 Staf (Cantika Dewi). Pekerjaan dan contoh milik Adovi dialihkan ke Cantika Dewi; contoh Studio \"Admin\" masuk sebagai Cantika Dewi. Error saat menekan Mode Staff diperbaiki.","en":"The prototype team is now 2 Super Admins (Jeck Rotama, Eka Poetra) and 1 Staff (Cantika Dewi). Adovi's work and examples moved to Cantika Dewi. The Staff mode toggle error is fixed."}}]},{"version":"1.1.0-dev.28","date":"2026-10-21","summary":{"id":"Manajemen Label dirancang ulang: kondisi label, rincian lengkap di samping, tab Verifikasi.","en":"Label Management redesigned: label health, full side details, a Verification tab."},"entries":[{"id":"dev28-labels-health","status":"prototype","where":{"role":"super","page":"labels9","menu":{"id":"Manajemen Label","en":"Label Management"}},"title":{"id":"Kondisi label hari ini & penyaring perhatian","en":"Label health today & attention filters"},"detail":{"id":"Pita biru merangkum label yang butuh perhatian (paket berakhir, dana ditahan, akses dibatasi, verifikasi), lalu penyaring Butuh perhatian · Akses dibatasi · Paket berakhir · Data lama · Multi-label. Daftar punya kotak cari, alasan perhatian tertulis di bawah nama, dan tombol › yang dobel dihapus.","en":"A blue band summarises labels needing attention, followed by filters (attention, restricted, plan ending, legacy data, multi-label). The list has search, shows reasons under each name, and the duplicate › button is gone."}},{"id":"dev28-labels-detail","status":"prototype","where":{"role":"super","page":"labels9","menu":{"id":"Manajemen Label","en":"Label Management"}},"title":{"id":"Rincian label lengkap di samping daftar","en":"Full label details beside the list"},"detail":{"id":"Ringkasan, perlu perhatian, identitas & dokumen, rekening, kontrak, paket-kredit-tarif, akses & tindakan, akun & multi-label, data lama, dan riwayat perubahan. Memanjang sesuai isi tanpa scroll di dalam kartu; tombol memakai aksi yang sudah ada (lihat kontrak, ubah tarif, perpanjang paket, periksa data).","en":"Summary, attention, identity & documents, bank account, contract, plan-credits-rate, access, account & multi-label, legacy data and change history, growing with content; buttons reuse existing actions."}},{"id":"dev28-labels-verify","status":"prototype","where":{"role":"super","page":"labels9","menu":{"id":"Manajemen Label","en":"Label Management"}},"title":{"id":"Tab Verifikasi & penggabungan Penyesuaian Data Label","en":"Verification tab & Label Data Updates merged"},"detail":{"id":"Pemeriksaan rekening, perubahan identitas, penggantian dokumen, pendaftaran, dan verifikasi identitas (AP-201) menjadi satu antrean. Menu Penyesuaian Data Label tidak lagi di sidebar; isinya menjadi penyaring Data lama dan bagian di rincian label. Calon member tampil sebagai tahapan Daftar → Bayar → Identitas → Rekening → Kontrak → Aktif.","en":"Bank, identity, document, application and identity-verification reviews share one queue. Label Data Updates leaves the sidebar and becomes the Legacy data filter and a detail section. Prospects show as stages."}}]},{"version":"1.1.0-dev.27","date":"2026-10-21","summary":{"id":"Pekerjaan dirancang ulang: satu daftar semua pekerjaan, alur waktu, dan rincian di samping.","en":"Work redesigned: one list of all work, a time flow and side details."},"entries":[{"id":"dev27-work-page","status":"prototype","where":{"role":"super","page":"mywork9","menu":{"id":"Pekerjaan","en":"Work"}},"title":{"id":"Pekerjaan: satu daftar untuk semua pekerjaan tim","en":"Work: one list for all team work"},"detail":{"id":"Menu “Pekerjaan Saya” menjadi “Pekerjaan”. Rilisan, klaim, tiket, persetujuan, penarikan, WAMI, layanan tambahan, dan transaksi tampil dalam satu daftar dengan penanggung jawab dan tenggat. Tombol di setiap baris membuka menu khususnya.","en":"“My Work” becomes “Work”. Releases, claims, tickets, approvals, withdrawals, WAMI, add-ons and transactions share one list with owner and deadline. Each row button opens its own menu."}},{"id":"dev27-work-flow","status":"prototype","where":{"role":"super","page":"mywork9","menu":{"id":"Pekerjaan","en":"Work"}},"title":{"id":"Berikutnya untukmu & alur waktu","en":"Next for you & time flow"},"detail":{"id":"Pita biru menunjukkan satu pekerjaan paling mendesak, lalu alur Terlambat → Hari ini → 7 hari → Nanti → Menunggu pihak lain. Klik titiknya untuk menampilkan kelompok itu saja. Kanan atas: ✓ jumlah selesai hari ini.","en":"A blue band shows the most urgent item, then a Late → Today → 7 days → Later → Waiting flow; click a point to filter. Top right: ✓ done today."}},{"id":"dev27-work-detail","status":"prototype","where":{"role":"super","page":"mywork9","menu":{"id":"Pekerjaan","en":"Work"}},"title":{"id":"Rincian di samping, memanjang sesuai isi","en":"Side details that grow with content"},"detail":{"id":"Klik pekerjaan untuk melihat tahapan, rincian rilisan atau transfer, lama → baru, aturan waktu, dan riwayat tanpa scroll di dalam kartu. Penanggung jawab bisa diganti, dan pekerjaan tanpa penanggung jawab bisa diambil.","en":"Click an item to see stages, release or payout details, old → new, timing rule and history without inner scrolling. Owner can be changed; unassigned work can be taken."}}]},{"version":"1.1.0-dev.26","date":"2026-10-20","summary":{"id":"Sidebar tanpa blok profil; nama & peran pindah ke tooltip foto header.","en":"Sidebar without the profile block; name & role move to the header photo tooltip."},"entries":[{"id":"dev26-sidebar-profile","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Sidebar","en":"Sidebar"}},"title":{"id":"Blok “Halo, nama” di sidebar dihapus","en":"Sidebar “Hello, name” block removed"},"detail":{"id":"Memberi ruang untuk menu. Nama dan peran (Super Admin, Admin, atau Label · paket) tampil saat kursor diarahkan ke foto di header.","en":"Frees room for the menu. Name and role show when hovering the header photo."}}]},{"version":"1.1.0-dev.25","date":"2026-10-19","summary":{"id":"Dashboard: aksi di samping foto, Kesehatan uang lebih mudah dibaca, kartu Pertumbuhan baru bergerak saat ganti metrik.","en":"Dashboard: actions next to the photo, easier Money health, new Growth card that animates between metrics."},"entries":[{"id":"dev25-decide","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · Perlu keputusan","en":"Dashboard · Decisions"}},"title":{"id":"Aksi muncul di samping foto","en":"Actions appear next to the photo"},"detail":{"id":"Tombol panah dihapus; foto penanggung jawab di paling kanan. Saat baris diarahkan, aksi spesifik (Bayar, Setujui, Tinjau, Balas) muncul di sebelah foto; klik di mana pun pada baris menjalankan aksinya.","en":"The arrow button is gone; the owner photo sits on the far right. On hover the specific action appears next to it; clicking anywhere on the row runs it."}},{"id":"dev25-money","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · Kesehatan uang","en":"Dashboard · Money health"}},"title":{"id":"Kesehatan uang: sisa kas setelah pembayaran","en":"Money health: cash left after payouts"},"detail":{"id":"Jarum rasio (1×, 1,5×, 4×) diganti angka sisa kas setelah semua pembayaran bulan ini, satu batang wajib dibayar vs sisa, dan satu kalimat penjelas. Status: Aman, Tipis (sisa kurang dari separuh kewajiban), atau Kurang.","en":"The ratio gauge is replaced by cash left after this month’s payouts, one due-vs-left bar and a plain sentence. Status: Safe, Thin (buffer under half of what is due) or Short."}},{"id":"dev25-growth","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · Pertumbuhan","en":"Dashboard · Growth"}},"title":{"id":"Kartu Pertumbuhan baru","en":"New Growth card"},"detail":{"id":"Enam metrik dalam satu panel; ringkasan di kiri (angka, pil persentase, kalimat wawasan) dan grafik di kanan. Saat metrik diganti, batang berubah tinggi dengan animasi dan angka menghitung, tanpa memuat ulang kartu.","en":"Six metrics in one panel; summary on the left and chart on the right. Switching metrics morphs the bars and counts the numbers without reloading the card."}}]},{"version":"1.1.0-dev.24","date":"2026-10-19","summary":{"id":"Dashboard Super Admin baru: Sorotan hari ini, Siklus royalti, Perlu keputusan, Kesehatan uang, Tim, Pertumbuhan.","en":"New Super Admin dashboard: Today’s highlight, Royalty cycle, Decisions, Money health, Team, Growth."},"entries":[{"id":"dev24-dashboard","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard","en":"Dashboard"}},"title":{"id":"Dashboard Super Admin dirombak","en":"Super Admin dashboard redesigned"},"detail":{"id":"Urutan baru: Sorotan hari ini di header → Siklus royalti (4 tahap + cincin hitung mundur) → Perlu keputusan Anda (satu daftar urut tenggat dengan tab dan tombol aksi saat diarahkan) + Kesehatan uang (jarum cakupan kas) → Tim hari ini → Pertumbuhan. Admin dan Label tidak berubah. Posisi kas dan 4 bulan awal grafik masih contoh.","en":"New order: Today’s highlight in the header → Royalty cycle (4 stages + countdown ring) → Needs your decision (one deadline-sorted list with tabs and hover actions) + Money health (cash-cover gauge) → Team today → Growth. Admin and Label unchanged. Cash position and the first 4 chart months are sample data."}},{"id":"dev24-motion","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard","en":"Dashboard"}},"title":{"id":"Gerak saat kartu terlihat","en":"Motion when cards come into view"},"detail":{"id":"Setiap kartu muncul sekali per sesi saat masuk layar: angka menghitung naik, batang & cincin terisi, jarum bergerak, grafik tumbuh. Tanpa gerak untuk pengguna “kurangi gerakan”.","en":"Each card animates once per session when it enters the viewport: counters, bars and rings fill, the gauge needle moves, the chart grows. No motion for “reduce motion” users."}}]},{"version":"1.1.0-dev.23","date":"2026-10-19","summary":{"id":"Pesan: chat label ↔ Rilis Musik dalam satu pintu; Kotak Masuk admin membaca semua percakapan label.","en":"Messages: one door for label ↔ Rilis Musik chat; the admin Inbox reads every label conversation."},"entries":[{"id":"dev23-pesan-label","status":"prototype","where":{"role":"label","page":"dashboard","menu":{"id":"Pesan (label)","en":"Messages (label)"}},"title":{"id":"Pesan: Tiket Bantuan menjadi chat","en":"Messages: Support Tickets become a chat"},"detail":{"id":"Menu Tiket Bantuan menjadi Pesan, dengan ikon chat di header label (titik merah bila ada balasan). “Pesan baru” untuk topik apa saja; “Permintaan khusus” membuka formulir katalog yang sudah ada. Setiap percakapan tetap tercatat sebagai tiket. Pengajuan pengembalian dana kini langsung membuka percakapan di Pesan.","en":"Support Tickets becomes Messages, with a chat icon in the label header (red dot on new replies). “New message” for any topic; “Special request” opens the existing catalogue forms. Every conversation is still recorded as a ticket. Refund requests now open a conversation in Messages directly."}},{"id":"dev23-pesan-super","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Kotak Masuk · Percakapan","en":"Inbox · Conversations"}},"title":{"id":"Kotak Masuk membaca semua percakapan label","en":"Inbox reads every label conversation"},"detail":{"id":"Balasan admin langsung sampai ke label dan otomatis menangani tiket; catatan internal tidak terlihat label; tombol Tangani, Tandai selesai, dan Rincian tiket di panel kanan.","en":"Admin replies reach the label and take the ticket automatically; internal notes stay hidden from labels; Take it, Mark as done and Ticket details in the side panel."}},{"id":"dev23-fixes","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Kotak Masuk","en":"Inbox"}},"title":{"id":"Perbaikan: urutan pesan & tiket umum","en":"Fixes: message order & general tickets"},"detail":{"id":"Urutan pesan dan catatan internal di Kotak Masuk kembali mengikuti jam. Tiket tanpa rilisan (permintaan umum, royalti) kini bisa diselesaikan.","en":"Inbox messages and internal notes follow their time again. Tickets without a release (general, royalty) can now be closed."}}]},{"version":"1.1.0-dev.22","date":"2026-10-19","summary":{"id":"Transisi layanan lama (Annual/VIP lifetime): pemberitahuan di aplikasi, pengembalian dana penuh, Berita untuk label.","en":"Legacy service transition (lifetime Annual/VIP): in-app notice, full refund, News for labels."},"entries":[{"id":"dev22-transition-label","status":"prototype","where":{"role":"label","page":"dashboard","menu":{"id":"Dashboard label · Nusantara Records","en":"Label dashboard · Nusantara Records"}},"title":{"id":"Pemberitahuan “Layanan Anda berubah”","en":"“Your service has changed” notice"},"detail":{"id":"Label layanan lama melihat layanan lamanya, paket baru gratis 1 tahun, dan jaminan pengembalian dana penuh berapa pun lama pemakaian. Batas pengajuan 30 hari sejak dibaca. Tombol pengajuan membuka Tiket Bantuan yang sudah terisi; setelah dibayar label pindah ke Basic. Data layanan lama masih contoh.","en":"Legacy-service labels see their previous service, the free 1-year plan, and a full-refund guarantee regardless of usage time. Requests close 30 days after reading. The request button opens a pre-filled support ticket; once paid the label moves to Basic. Legacy data is sample data."}},{"id":"dev22-refund-super","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Pekerjaan Saya · Pengembalian dana","en":"My Work · Refunds"}},"title":{"id":"Keputusan pengembalian dana (Super Admin)","en":"Refund decisions (Super Admin)"},"detail":{"id":"Pengajuan masuk ke Pekerjaan Saya, notifikasi, dan Kotak Masuk. Alur: Diajukan → Bukti diperiksa → Disetujui → Dibayar (label pindah ke Basic) atau Ditolak dengan alasan. Hanya Super Admin.","en":"Requests land in My Work, notifications and Inbox. Flow: Submitted → Proof check → Approved → Paid (label moves to Basic) or Declined with a reason. Super Admin only."}},{"id":"dev22-news-super","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Kotak Masuk · Berita","en":"Inbox · News"}},"title":{"id":"Berita: siaran ke label tanpa email","en":"News: broadcasts to labels without email"},"detail":{"id":"Tab baru di Kotak Masuk. Super Admin menulis berita untuk semua label aktif atau label layanan lama; label melihatnya sebagai jendela wajib dibaca. Tercatat siapa yang sudah membaca, serta nilai maksimum pengembalian dana bila semua mengajukan.","en":"New Inbox tab. Super Admin writes news for all active labels or legacy-service labels; labels see it as a must-read window. Read receipts are recorded, plus the maximum refund if everyone requests."}}]},{"version":"1.1.0-dev.21","date":"2026-10-18","summary":{"id":"Profil: Kota diganti ID staf; halaman demo motion graphic (/motion-demo131.html).","en":"Profile: City replaced by Staff ID; motion graphics demo page (/motion-demo131.html)."},"entries":[{"id":"dev21-staffid","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Profil · Data akun","en":"Profile · Account data"}},"title":{"id":"ID staf menggantikan Kota","en":"Staff ID replaces City"},"detail":{"id":"Format STF-YYMM-NNN (bulan bergabung + urutan staf). Hanya tampil, tidak bisa diubah sendiri; kota tetap tampil di pita identitas. Direktori wilayah tidak lagi dimuat oleh halaman Profil.","en":"Format STF-YYMM-NNN (join month + staff order). Display only, not self-editable; the city still shows in the identity band. The region directory is no longer loaded by the Profile page."}},{"id":"dev21-motion-demo","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Demo motion","en":"Motion demo"}},"title":{"id":"Halaman demo motion graphic","en":"Motion graphics demo page"},"detail":{"id":"Tujuh contoh tanpa library: angka menghitung & batang terisi, transisi data per periode, umpan balik aksi (tahap tiket, kirim pesan, simpan), momen penting (pencairan tuntas + konfeti + seal), status kosong, kerangka memuat, transisi antar tampilan. Ada sakelar \"Kurangi gerakan\" dan tema gelap.","en":"Seven examples with no library: counting numbers & filling bars, per-period data transitions, action feedback (ticket stage, send message, save), milestone moments (payout complete + confetti + seal), empty state, loading skeleton, view transitions. Includes a \"Reduce motion\" switch and dark theme."}}]},{"version":"1.1.0-dev.20","date":"2026-10-18","summary":{"id":"Tooltip batang Penarikan melayang di atas halaman: bagian hijau kini punya info, dan tooltip tidak terpotong tepi kartu.","en":"Withdrawals bar tooltips float above the page: the green part now has info, and tooltips are no longer clipped by the card edge."},"entries":[{"id":"dev20-ftip","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · Penarikan periode ini","en":"Dashboard · Period Withdrawals"}},"title":{"id":"Tooltip melayang untuk tiap bagian batang","en":"Floating tooltip for each bar segment"},"detail":{"id":"Tooltip kini elemen melayang di atas halaman (bukan di dalam kartu): mengikuti kursor, tidak terpotong tepi kartu, dan dijepit agar tetap di dalam layar. Bagian hijau (dibayar) yang sebelumnya tertutup kini menampilkan infonya.","en":"Tooltips are now a floating element above the page (not inside the card): they follow the cursor, are not clipped by the card edge and stay within the screen. The green (paid) part, previously covered, now shows its info."}}]},{"version":"1.1.0-dev.19","date":"2026-10-17","summary":{"id":"Profil & Kotak Masuk mengisi satu layar tanpa gulir; kolom Kota memakai data wilayah label; kartu Penarikan dengan tooltip per bagian batang; analisis Pemantauan Keuangan.","en":"Profile & Inbox fill one screen without scrolling; City field uses the label region data; Withdrawals card with per-segment bar tooltips; Financial Monitoring analysis."},"entries":[{"id":"dev19-fit","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Profil & Kotak Masuk","en":"Profile & Inbox"}},"title":{"id":"Satu layar penuh tanpa gulir","en":"One full screen, no scrolling"},"detail":{"id":"Penyebab gulir: footer prototype + padding bawah + tinggi minimum 100vh di bawah header. Di kedua halaman itu dihapus; konten mengisi tinggi layar (diuji 1366×768, 1440×900, 1920×1080) dengan jarak lega di dalam kartu.","en":"Scroll cause: prototype footer + bottom padding + a 100vh minimum height below the header. Removed on both pages; content fills the screen height (tested 1366×768, 1440×900, 1920×1080) with comfortable spacing inside the cards."}},{"id":"dev19-city","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Profil · Data akun","en":"Profile · Account data"}},"title":{"id":"Alamat → Kota, dari direktori wilayah yang sama dengan label","en":"Address → City, from the same region directory as labels"},"detail":{"id":"Isian Kota menyarankan 514 kab/kota dari direktori wilayah yang sudah dipakai label (dimuat-belakangan; tidak ada data baru atau duplikat). Kota di luar daftar ditolak; nilai lama tetap bisa disimpan selama tidak diubah.","en":"The City field suggests 514 regencies/cities from the region directory labels already use (lazy-loaded; no new or duplicated data). Cities outside the list are rejected; an old value can be kept if unchanged."}},{"id":"dev19-withdraw","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · Penarikan periode ini","en":"Dashboard · Period Withdrawals"}},"title":{"id":"Penarikan: tooltip per bagian batang, tanpa keterangan jadwal","en":"Withdrawals: per-segment bar tooltips, no schedule note"},"detail":{"id":"Keterangan \"pengajuan ditutup 14 Sep\" dihapus (sudah diketahui Super Admin). Hover tiap bagian batang menampilkan informasinya sendiri: dibayar · diajukan belum dibayar · tidak diajukan. Tiga angka di bawah batang memakai warna yang sama dengan bagiannya; dua bisa diklik.","en":"The \"requests closed Sep 14\" note is gone (Super Admins already know it). Hovering each bar segment shows its own info: paid · requested unpaid · not requested. The three numbers below use the same colours as their segments; two are clickable."}},{"id":"dev19-monitor-analysis","status":"prototype","where":{"role":"super","page":"liability9","menu":{"id":"Pemantauan Keuangan","en":"Financial Monitoring"}},"title":{"id":"Analisis Pemantauan Keuangan (dokumen, belum diterapkan)","en":"Financial Monitoring analysis (document, not applied)"},"detail":{"id":"prototype-rilis-musik/ANALISIS-PEMANTAUAN-KEUANGAN.md: struktur tab, tumpang tindih Pemantauan Dana vs Kewajiban Royalti, kepadatan tabel, status kosong, catatan data untuk aplikasi asli, dan urutan perbaikan.","en":"prototype-rilis-musik/ANALISIS-PEMANTAUAN-KEUANGAN.md: tab structure, Funds Monitor vs Royalty Payable overlap, table density, empty states, data notes for the real app, and a fix order."}}]},{"version":"1.1.0-dev.18","date":"2026-10-16","summary":{"id":"Foto profil: menu saat hover + atur dengan geser/gulir; mata kata sandi; kartu Penarikan diringkas; CH-A (chat lebih dulu) dengan Notifikasi di halaman yang sama; tab baru Kewajiban Royalti di Pemantauan Keuangan.","en":"Profile photo: hover menu + drag/scroll to adjust; password eye; Period Withdrawals card simplified; CH-A (chat first) with Notifications on the same page; new Royalty Payable tab in Financial Monitoring."},"entries":[{"id":"dev18-photo","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Profil · foto & kata sandi","en":"Profile · photo & password"}},"title":{"id":"Foto: pilihan muncul saat hover; ukuran & posisi tanpa slider; mata kata sandi","en":"Photo: options on hover; size & position without a slider; password eye"},"detail":{"id":"Tombol \"Unggah foto\" yang berdiri sendiri dihapus. Arahkan kursor ke foto → Unggah/Ganti · Atur · Hapus. Mode atur: geser untuk posisi, gulir roda atau cubit dua jari untuk ukuran (+/− dan panah dari keyboard); Simpan/Batal melayang di bawah lingkaran sehingga tata letak tidak bergeser. Tiga isian kata sandi punya tombol mata.","en":"The standalone \"Upload photo\" button is gone. Hover the photo → Upload/Replace · Adjust · Remove. Adjust mode: drag to position, scroll wheel or two-finger pinch to resize (+/− and arrows from the keyboard); Save/Cancel float under the circle so the layout does not shift. All three password fields have an eye toggle."}},{"id":"dev18-payout-simple","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · Penarikan periode ini","en":"Dashboard · Period Withdrawals"}},"title":{"id":"Penarikan periode ini diringkas","en":"Period Withdrawals simplified"},"detail":{"id":"Satu angka utama (diajukan / maksimal bulan ini), dua angka yang perlu tindakan (belum dibayar dengan tenggat · tidak diajukan → Kewajiban Royalti), satu batang tiga warna dengan legenda satu baris, dan satu baris konteks laporan.","en":"One headline (requested / this month’s maximum), two numbers that need action (unpaid with deadline · not requested → Royalty Payable), one three-colour bar with a one-line legend, and one line of report context."}},{"id":"dev18-cha","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Header · Kotak Masuk","en":"Header · Inbox"}},"title":{"id":"Kotak Masuk CH-A: percakapan lebih dulu, notifikasi di halaman yang sama","en":"Inbox CH-A: conversations first, notifications on the same page"},"detail":{"id":"Daftar (pengalih Percakapan | Notifikasi, tab Semua · Label & tiket · Internal, cari, saringan menunggu jawabanku) · percakapan (balasan cepat, Balas ke label / Catatan internal, linimasa berurutan waktu) · konteks tiket (rincian, tahapan, tindakan lanjut tahap / teruskan ke distributor / buka rilisan, info label, aktivitas terkait). Mode Notifikasi memakai kolom yang sama; notifikasi menunjuk percakapan terkait. Lonceng → \"Buka Kotak Masuk\" membuka mode Notifikasi.","en":"List (Conversations | Notifications switch, All · Labels & tickets · Internal tabs, search, awaiting-my-reply filter) · conversation (quick replies, Reply to label / Internal note, time-ordered timeline) · ticket context (details, stages, actions: next stage / forward to distributor / open release, label info, related activity). Notification mode uses the same columns; notifications link to the related conversation. Bell → \"Open Inbox\" opens notification mode."}},{"id":"dev18-payable","status":"prototype","where":{"role":"super","page":"liability9","menu":{"id":"Pemantauan Keuangan · Kewajiban Royalti","en":"Financial Monitoring · Royalty Payable"}},"title":{"id":"Tab baru: Kewajiban Royalti (rekap bulanan saldo belum dicairkan)","en":"New tab: Royalty Payable (monthly recap of unpaid balances)"},"detail":{"id":"Ringkasan kewajiban berjalan (siap cair tidak diajukan + di bawah ambang Rp 1 jt; yang sedang dibayar dipisah), tren per laporan (grafik + tabel: royalti laporan, bisa dicairkan, diajukan, tidak diajukan, di bawah ambang, kewajiban), umur saldo, dan daftar label dengan saringan & tombol \"Kirim pengingat\". Rekap bulanan & umur = data pratinjau; daftar label dari saldo label prototype.","en":"Running payable summary (withdrawable not requested + below the Rp 1M threshold; balances being paid shown separately), per-report trend (chart + table: report royalties, withdrawable, requested, not requested, below threshold, payable), balance age, and a label list with filters & \"Send reminder\". Monthly recap & age = preview data; label list from prototype label balances."}}]},{"version":"1.1.0-dev.17","date":"2026-10-16","summary":{"id":"Profil: ubah data akun & kata sandi langsung di kartu; kartu Penarikan periode ini mengikuti siklus bulanan (laporan → potensi ≥ Rp 1 jt → pengajuan s.d. tgl 14 → sisa ke pemantauan).","en":"Profile: edit account data & password right inside the cards; Period Withdrawals follows the monthly cycle (report → potential ≥ Rp 1M → requests until the 14th → remainder to monitoring)."},"entries":[{"id":"dev17-profile-inline","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Header · avatar → Profil","en":"Header · avatar → Profile"}},"title":{"id":"Ubah data akun & kata sandi langsung di kartu","en":"Edit account data & password inside the cards"},"detail":{"id":"Kartu Kinerja dihapus, diganti kartu Kata sandi berisi isian langsung (meter kekuatan, validasi). \"Ubah\" di Data akun mengubah kartu menjadi isian di tempat dengan Simpan/Batal (Esc membatalkan) — tidak lagi membuka panel dari kanan. Tetap muat 1366×768.","en":"The Performance card is removed and replaced by a Password card with inline fields (strength meter, validation). \"Edit\" on Account data turns the card into in-place fields with Save/Cancel (Esc cancels) — no side panel. Still fits 1366×768."}},{"id":"dev17-payout-cycle","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · Penarikan periode ini","en":"Dashboard · Period Withdrawals"}},"title":{"id":"Penarikan periode ini mengikuti siklus bulanan","en":"Period Withdrawals follows the monthly cycle"},"detail":{"id":"Ringkasan laporan Believe (total royalti, bisa dicairkan ≥ Rp 1 jt + jumlah label, di bawah ambang yang bergulir); angka utama \"Diajukan dari maksimal\"; batang berskala potensi maksimal: dibayar · menunggu bayar · diperiksa · belum/tidak diajukan; garis waktu 2 (laporan) · 14 (tutup pengajuan) · 20 (batas bayar) · laporan berikutnya dengan penanda hari ini; dua ajakan: sisa belum dibayar & sisa tidak diajukan → Pemantauan Royalti. Angka laporan/potensi = data pratinjau.","en":"Believe report summary (total royalties, withdrawable ≥ Rp 1M + label count, below-threshold carried over); headline \"Requested of maximum\"; bar scaled to the maximum potential: paid · awaiting payment · in review · not (yet) requested; timeline 2 (report) · 14 (requests close) · 20 (payment due) · next report with a today marker; two calls to action: unpaid remainder & unrequested remainder → Royalty Monitoring. Report/potential figures are preview data."}}]},{"version":"1.1.0-dev.16","date":"2026-10-16","summary":{"id":"Profil tanpa judul dengan pita identitas & sorotan kinerja; kartu Penarikan periode ini versi W-B; Geografi menampilkan \"x/y lokasi lengkap\" + \"Lihat & lengkapi\"; header halaman lain penuh seperti Home.","en":"Title-less Profile with an identity band & performance highlights; Period Withdrawals card in the W-B layout; Geography shows \"x/y complete locations\" + \"View & complete\"; other header pages use the full-width bar like Home."},"entries":[{"id":"dev16-profile","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Header · avatar → Profil","en":"Header · avatar → Profile"}},"title":{"id":"Profil: pita identitas, sorotan, kinerja — tetap satu layar","en":"Profile: identity band, highlights, performance — still one screen"},"detail":{"id":"Tanpa judul/subjudul halaman. Pita atas berisi foto (tanpa bayangan, bisa diatur langsung), nama, peran, kontak, dan tiga sorotan: masa kerja (sejak tanggal bergabung · jenis kontrak), pekerjaan tuntas bulan terakhir, sesi aktif. Di bawahnya: Data akun · Kinerja (batang ditangani vs tuntas per bulan, isu, cuti terpakai, status KPI) · Keamanan & tampilan. Muat penuh di 1366×768.","en":"No page title/subtitle. The top band holds the photo (no shadow, editable in place), name, role, contact and three highlights: tenure (join date · contract type), work closed last month, active sessions. Below: Account data · Performance (handled vs closed bars per month, issues, leave used, KPI status) · Security & appearance. Fits fully on 1366×768."}},{"id":"dev16-withdraw-wb","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · Penarikan periode ini","en":"Dashboard · Period Withdrawals"}},"title":{"id":"Penarikan periode ini: satu batang alur status (W-B)","en":"Period Withdrawals: one status-flow bar (W-B)"},"detail":{"id":"Batang dibagi dibayar · menunggu pembayaran · menunggu pemeriksaan; angka dan jumlah pengajuan di bawah tiap bagian; kalimat tindakan \"Sisa Rp … harus dibayar sebelum 21 Sep (n hari lagi)\" dengan tombol ke daftar pengajuan. Rincian status diambil dari data pengajuan prototype (WD-091 menunggu pemeriksaan, WD-092 menunggu pembayaran).","en":"The bar splits paid · awaiting payment · awaiting review; amounts and request counts under each part; an action sentence \"Remaining Rp … must be paid before 21 Sep (n days left)\" with a button to the request list. The status split comes from the prototype requests (WD-091 awaiting review, WD-092 awaiting payment)."}},{"id":"dev16-geo","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · Geografi anggota","en":"Dashboard · Member Geography"}},"title":{"id":"Geografi: \"x/y lokasi lengkap\" + \"Lihat & lengkapi\"","en":"Geography: \"x/y complete locations\" + \"View & complete\""},"detail":{"id":"Kaki kartu kini menunjukkan cincin kelengkapan lokasi dan tombol ke daftar lokasi belum lengkap, menggantikan tautan polos \"Lokasi belum lengkap · n\".","en":"The card footer now shows a location-completeness ring and a button to the incomplete-location list, replacing the plain \"Location incomplete · n\" link."}},{"id":"dev16-header","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Header · halaman selain Home","en":"Header · pages other than Home"}},"title":{"id":"Bar header halaman lain penuh kiri–kanan seperti Home","en":"Header bar on other pages is full-width like Home"},"detail":{"id":"Keuangan, Staf & Akses, Pengaturan, Kotak Masuk, dan Profil tidak lagi memakai bar yang menjorok dengan sudut bawah membulat (konten terlihat di tepi saat digulir).","en":"Finance, Staff & Access, Settings, Inbox and Profile no longer use an inset bar with rounded bottom corners (content showed at the edges when scrolling)."}}]},{"version":"1.1.0-dev.15","date":"2026-10-16","summary":{"id":"Profil muat satu layar (tiga kolom, tanpa gulir); ikon Kotak Masuk di menu header tepat setelah Home.","en":"Profile fits one screen (three columns, no scrolling); Inbox icon in the header menu right after Home."},"entries":[{"id":"dev15-profile","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Header · avatar → Profil","en":"Header · avatar → Profile"}},"title":{"id":"Profil dirapikan: satu layar tanpa gulir","en":"Profile tidied: one screen, no scrolling"},"detail":{"id":"Tiga kolom sejajar: foto & identitas · data akun (kisi dua kolom) + tampilan & bahasa · keamanan. Tombol aksi pindah ke kepala kelompok, catatan panjang jadi tooltip, foto 112 px. Diuji muat penuh pada layar 1440×1000 dan 1366×768.","en":"Three aligned columns: photo & identity · account data (two-column grid) + appearance & language · security. Action buttons moved to group headers, long notes became tooltips, 112 px photo. Verified to fit fully on 1440×1000 and 1366×768 screens."}},{"id":"dev15-inbox-icon","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Header · menu ikon","en":"Header · icon menu"}},"title":{"id":"Ikon Kotak Masuk di menu header, setelah Home","en":"Inbox icon in the header menu, after Home"},"detail":{"id":"Membuka halaman Kotak Masuk; aktif (lingkaran gelap) saat halaman terbuka dan Home tidak ikut aktif; titik merah bila ada notifikasi belum dibaca atau percakapan menunggu jawaban. Desain ulang halaman Kotak Masuk menyusul.","en":"Opens the Inbox page; active (dark circle) while the page is open and Home is not; red dot when there are unread notifications or conversations awaiting a reply. Inbox page redesign to follow."}}]},{"version":"1.1.0-dev.14","date":"2026-10-16","summary":{"id":"Chip gelap tanpa garis merah muda di ujung kanan; panah kartu ringkasan hanya bereaksi saat panah di-hover; Kotak Masuk & Profil tanpa sidebar aplikasi; Profil hanya akun; saklar disamakan dengan referensi.","en":"Dark chips without the pink right edge; summary-card arrow reacts only when the arrow is hovered; Inbox & Profile without the app sidebar; Profile is account-only; switch matched to the reference."},"entries":[{"id":"dev14-chip-edge","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · daftar pekerjaan · tema gelap","en":"Dashboard · work list · dark theme"}},"title":{"id":"Chip penanda gelap: hanya lengkung kiri yang berwarna","en":"Dark indicator chips: only the left curve is coloured"},"detail":{"id":"Penyebab garis di ujung kanan: lapisan warna kiri berulang ke kolom tepi kanan karena hanya lapisan terakhir yang memakai border-box. Semua lapisan kini border-box tanpa ulang; warna kanan dihilangkan dan bayangan dibuat lebih rendah, sehingga chip sama logikanya dengan pil metrik.","en":"Cause of the right-edge line: the left colour layer repeated into the right border column because only the last layer used border-box. All layers are now border-box with no repeat; the right colour is removed and the shadow lowered, so chips follow the same logic as the metric pill."}},{"id":"dev14-arrow-hover","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · kartu ringkasan","en":"Dashboard · summary cards"}},"title":{"id":"Tombol panah berubah warna hanya saat panah di-hover","en":"Arrow button changes colour only when the arrow is hovered"},"detail":{"id":"Zona panah 28 px ditambahkan di atas lingkaran panah; hover pada bagian kartu lain tidak lagi mengubah panah. Klik di mana pun pada kartu tetap membuka rincian; fokus keyboard tetap menyorot panah.","en":"A 28 px arrow zone sits over the arrow circle; hovering elsewhere on the card no longer changes it. Clicking anywhere on the card still opens the detail; keyboard focus still highlights the arrow."}},{"id":"dev14-no-sidebar","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Kotak Masuk & Profil","en":"Inbox & Profile"}},"title":{"id":"Kotak Masuk & Profil sebagai halaman header, tanpa sidebar aplikasi","en":"Inbox & Profile as header pages, without the app sidebar"},"detail":{"id":"Keduanya dibuka dari header (lonceng/chat/avatar); sidebar aplikasi disembunyikan karena Kotak Masuk punya navigasinya sendiri. Profil kini hanya Akun (foto, data, tampilan & bahasa, keamanan); \"Label & akses\" dan \"Preferensi notifikasi\" dilepas untuk ditempatkan di menu lain bila diperlukan.","en":"Both open from the header (bell/chat/avatar); the app sidebar is hidden because the Inbox has its own navigation. Profile is now Account only (photo, data, appearance & language, security); \"Labels & access\" and \"Notification preferences\" are removed, to be placed elsewhere if needed."}},{"id":"dev14-switch","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Komponen · saklar","en":"Component · switch"}},"title":{"id":"Saklar disamakan dengan referensi (bevel)","en":"Switch matched to the reference (bevel)"},"detail":{"id":"Rasio 1,68 : 1; trek hijau bergradasi diagonal dengan tepi hijau gelap, bayangan dalam dari kiri-atas dan sorot dalam di bawah; knop #f3f3f3 bercincin putih tipis dengan bayangan ke kiri; bayangan luar lembut. Varian gelap disertakan.","en":"1.68 : 1 ratio; diagonal green gradient track with a dark-green edge, inner shadow from top-left and inner highlight at the bottom; #f3f3f3 knob with a thin white ring and leftward shadow; soft outer shadow. Dark variant included."}}]},{"version":"1.1.0-dev.13","date":"2026-10-16","summary":{"id":"Saklar hijau standar; Profil kiri–kanan dengan pengatur foto langsung; Kotak Masuk tiga kolom (notifikasi, tiket & label, internal); popover chat tidak lagi terpotong; kaca gelap memakai logika yang sama dengan terang.","en":"Standard green switch; left–right Profile with inline photo editor; three-column Inbox (notifications, tickets & labels, internal); chat popover no longer clipped; dark glass uses the same logic as light."},"entries":[{"id":"dev13-switch","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Profil · Preferensi notifikasi","en":"Profile · Notification preferences"}},"title":{"id":"Saklar standar: hijau saat aktif (dari referensi)","en":"Standard switch: green when on (from the reference)"},"detail":{"id":"Rasio dan warna diukur dari referensi: trek hijau bergradasi (kiri gelap → kanan terang, bayangan dalam di atas), knop putih dengan bayangan lembut, trek abu cekung saat nonaktif. Kelas .sw131 menjadi standar untuk saklar baru.","en":"Ratio and colours measured from the reference: gradient green track (dark left → light right, inner top shadow), white knob with soft shadow, recessed grey track when off. Class .sw131 is the standard for new switches."}},{"id":"dev13-profile","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Header · avatar → Profil","en":"Header · avatar → Profile"}},"title":{"id":"Profil kiri–kanan + atur foto langsung di kolom foto","en":"Left–right Profile + edit the photo right in the photo column"},"detail":{"id":"Kolom kiri: foto (unggah, geser untuk posisi, slider ukuran, simpan/batal, hapus) dan identitas. Kolom kanan: Data akun dalam kisi tiga kolom, Tampilan & bahasa berdampingan dengan Keamanan. Foto tersimpan sebagai potongan 256 px dan langsung dipakai avatar header & sidebar.","en":"Left column: photo (upload, drag to position, size slider, save/cancel, remove) and identity. Right column: account data in a three-column grid, Appearance & language beside Security. The photo is saved as a 256 px crop and used by the header & sidebar avatars right away."}},{"id":"dev13-inbox","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Kotak Masuk","en":"Inbox"}},"title":{"id":"Kotak Masuk tiga kolom: navigasi · daftar · detail","en":"Three-column Inbox: navigation · list · detail"},"detail":{"id":"Kiri: Notifikasi per jenis dan Percakapan (Semua · Tiket & label · Internal) dengan hitungan. Pembeda jenis: tiket = avatar label + ID + chip status; internal = gembok + tag. Tiket menampilkan tahapan dan satu linimasa berisi pesan label serta catatan internal (garis putus-putus + gembok); composer bisa beralih \"Balas ke label\" / \"Catatan internal\". Ruang internal diberi pita \"tidak terlihat oleh label\".","en":"Left: Notifications by type and Conversations (All · Tickets & labels · Internal) with counts. Type cues: ticket = label avatar + ID + status chip; internal = lock + tag. A ticket shows its stages and one timeline of label messages plus internal notes (dashed + lock); the composer switches between \"Reply to label\" / \"Internal note\". The internal room carries a \"not visible to labels\" strip."}},{"id":"dev13-popover","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Header · chat","en":"Header · chat"}},"title":{"id":"Popover chat tidak terpotong; jarak tautan & tombol tutup","en":"Chat popover no longer clipped; spacing between link & close"},"detail":{"id":"Kartu header tidak lagi overflow:hidden (lapisan atmosfer dipotong sendiri), sehingga popover tampil utuh di atas konten.","en":"The header card is no longer overflow:hidden (atmosphere layers clip themselves), so the popover shows in full above the content."}},{"id":"dev13-dark-glass","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · tema gelap","en":"Dashboard · dark theme"}},"title":{"id":"Kaca gelap = logika terang: warna hanya di lengkung ujung, bergradasi","en":"Dark glass = light logic: colour only on the end curves, graded"},"detail":{"id":"Analisis: di terang, rim atas/bawah putih opak menutup lapisan warna sehingga warna hanya tampak di lengkung kiri (kuat) & kanan (lembut). Di gelap rim tembus pandang, jadi warna terlihat mengelilingi pil seperti outline. Kini lapisan warna memudar sendiri ke atas/bawah (radial 14 px di ujung), sorot atas sangat tipis, tanpa semburat warna di isi.","en":"Analysis: in light, the opaque white top/bottom rim covers the colour layer so colour only shows on the left (strong) & right (soft) curves. In dark the rim is translucent, so colour ringed the pill like an outline. The colour layer now fades by itself towards top/bottom (14 px radial at the ends), very thin top highlight, no colour wash in the fill."}}]},{"version":"1.1.0-dev.12","date":"2026-10-16","summary":{"id":"Popover ringkas lonceng/chat kembali (+ tautan Kotak Masuk); Chat Center dua panel; Profil dirancang ulang sebagai daftar pengaturan; kaca tema gelap menyatu dengan kartu; ikon toggle hanya saat bergeser; audit Kamus Penanda.","en":"Quick bell/chat popovers are back (+ Inbox link); two-pane Chat Center; Profile redesigned as a settings list; dark glass blends with the card; toggle icon only while sliding; Indicator Guide audit."},"entries":[{"id":"dev12-popover","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Header · lonceng & chat","en":"Header · bell & chat"}},"title":{"id":"Popover ringkas tetap, dengan tautan \"Buka Kotak Masuk\"","en":"Quick popover kept, with an \"Open Inbox\" link"},"detail":{"id":"Lonceng dan ikon chat membuka tampilan cepat seperti semula; judul popover diberi tautan ke halaman Kotak Masuk.","en":"The bell and chat icons open the quick view as before; the popover title links to the Inbox page."}},{"id":"dev12-chat-center","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Kotak Masuk · Percakapan","en":"Inbox · Conversations"}},"title":{"id":"Chat Center: daftar thread di kiri, percakapan di kanan","en":"Chat Center: thread list on the left, conversation on the right"},"detail":{"id":"Thread = chat label, chat internal, tiket. Pencarian, saringan \"menunggu jawabanku\" (pesan terakhir bukan dariku), penanda status Kamus, gelembung pesan milikku/lawan bicara, kotak balasan (Enter mengirim, Shift+Enter baris baru). Balasan tersimpan di data lokal.","en":"Threads = label chat, internal chat, tickets. Search, \"awaiting my reply\" filter (last message not mine), Guide status indicator, my/their message bubbles, composer (Enter sends, Shift+Enter new line). Replies are stored locally."}},{"id":"dev12-profile","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Header · avatar → Profil","en":"Header · avatar → Profile"}},"title":{"id":"Profil dirancang ulang: kartu identitas + daftar pengaturan","en":"Profile redesigned: identity card + settings list"},"detail":{"id":"Satu kolom 820 px: kartu identitas (avatar, nama, email, chip peran & akses, tombol ubah), tab, lalu kelompok baris \"judul · keterangan · kontrol di kanan\". Formulir panjang dipindah ke drawer (ubah data, ubah kata sandi); saklar kecil untuk preferensi; tanpa ikon (i) yatim.","en":"One 820 px column: identity card (avatar, name, email, role & access chips, edit button), tabs, then groups of \"title · description · control on the right\" rows. Long forms moved to drawers (edit data, change password); small switches for preferences; no orphan (i) icons."}},{"id":"dev12-dark-glass","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · tema gelap","en":"Dashboard · dark theme"}},"title":{"id":"Kaca tema gelap menyatu dengan kartu (varian G)","en":"Dark glass blends with the card (variant G)"},"detail":{"id":"Tanpa garis rim yang terbaca, tanpa bayangan lebar; isi hanya +4 L* dari kartu; kesan kaca dari sorot atas berupa gradien lembut dan warna penanda sebagai cahaya di sisi kiri (radial), bukan garis. Ikon toggle tema hanya muncul saat knop bergeser.","en":"No readable rim line, no wide shadow; fill only +4 L* above the card; the glass feel comes from a soft gradient top highlight and the indicator colour as a glow on the left side (radial), not a line. The theme-toggle icon appears only while the knob slides."}},{"id":"dev12-kamus-audit","status":"prototype","where":{"role":"super","page":"standards9","menu":{"id":"Standar & Penanda · Kamus Penanda","en":"Standards & Indicators · Indicator Guide"}},"title":{"id":"Audit Kamus Penanda (dokumen, belum diterapkan)","en":"Indicator Guide audit (document, not applied yet)"},"detail":{"id":"prototype-rilis-musik/AUDIT-KAMUS-PENANDA.md: 8 temuan fungsi/struktur, 9 kata, 8 warna, penyesuaian ke chip kaca, dan daftar ubah/kembangkan/hapus. Menunggu keputusan pemilik untuk K5, K7, W3–W5.","en":"prototype-rilis-musik/AUDIT-KAMUS-PENANDA.md: 8 function/structure findings, 9 wording, 8 colour, alignment with glass chips, and a change/develop/remove list. Awaiting owner decisions on K5, K7, W3–W5."}}]},{"version":"1.1.0-dev.11","date":"2026-10-16","summary":{"id":"Dua halaman baru: Kotak Masuk (Notifikasi | Percakapan) dari lonceng/ikon chat, dan Profil (Akun · Label & akses · Preferensi notifikasi) dari avatar.","en":"Two new pages: Inbox (Notifications | Conversations) from the bell/chat icons, and Profile (Account · Labels & access · Notification preferences) from the avatar."},"entries":[{"id":"dev11-inbox","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Header · lonceng & chat → Kotak Masuk","en":"Header · bell & chat → Inbox"}},"title":{"id":"Kotak Masuk: notifikasi per hari + percakapan dalam satu halaman","en":"Inbox: notifications per day + conversations on one page"},"detail":{"id":"Lonceng dan ikon chat tidak lagi membuka popover kecil, melainkan halaman penuh dengan dua tab. Notifikasi dikelompokkan per hari, difilter per jenis (Pembayaran, Rilisan, Tiket & chat, Personal, Sistem), \"Tandai semua dibaca\", dan setiap baris mengarah ke objeknya. Percakapan memuat chat label, chat internal, dan tiket bantuan dengan penanda status dari Kamus; membuka thread memakai tampilan chat yang sudah ada.","en":"The bell and chat icons no longer open a small popover but a full page with two tabs. Notifications are grouped per day, filtered by type (Payments, Releases, Tickets & chat, Personal, System), \"Mark all read\", and every row links to its object. Conversations list label chat, internal chat and support tickets with Guide status indicators; opening a thread uses the existing chat view."}},{"id":"dev11-profile","status":"prototype","where":{"role":"super","page":"module","menu":{"id":"Header · avatar → Profil","en":"Header · avatar → Profile"}},"title":{"id":"Profil: halaman khusus saat avatar diklik","en":"Profile: a dedicated page when the avatar is clicked"},"detail":{"id":"Tiga tab. Akun: data akun (ubah lewat drawer yang sudah ada), tema & bahasa, ganti kata sandi (validasi: minimal 10 karakter, ulangan harus sama), sesi aktif dengan keluar dari perangkat lain. Label & akses: peran, status akses, daftar kewenangan memakai penanda Kamus. Preferensi notifikasi: kanal dalam-aplikasi / email per jenis kejadian, tersimpan di browser.","en":"Three tabs. Account: account data (edited via the existing drawer), theme & language, change password (validation: at least 10 characters, repeat must match), active sessions with sign-out of other devices. Labels & access: role, access status, permission list using Guide indicators. Notification preferences: in-app / email channel per event type, saved in the browser."}}]},{"version":"1.1.0-dev.10","date":"2026-10-16","summary":{"id":"Satu standar kaca untuk pil & chip: rim chip kini benar-benar berwarna penanda; tema gelap dirancang ulang sebagai lempeng kaca (bukan outline putih).","en":"One glass standard for pill & chip: the chip rim now truly carries the indicator colour; dark theme redesigned as a glass slab (not a white outline)."},"entries":[{"id":"dev10-chip-rim","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · daftar pekerjaan","en":"Dashboard · work list"}},"title":{"id":"Rim chip mengikuti warna penanda (perbaikan dev.9)","en":"Chip rim follows the indicator colour (dev.9 fix)"},"detail":{"id":"Di dev.9 rim chip tampak abu karena deklarasi warna penanda tertimpa aturan chip yang lebih tua; kini warna penanda (--status111) dipakai sekali untuk titik dan rim, teks tetap netral. Pil dan chip memakai satu set variabel yang sama — chip hanya versi berskala.","en":"In dev.9 the chip rim looked grey because the indicator-colour declaration was overridden by an older chip rule; now the indicator colour (--status111) is used once for the dot and the rim, text stays neutral. Pill and chip share one set of variables — the chip is just a scaled version."}},{"id":"dev10-dark-glass","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · tema gelap","en":"Dashboard · dark theme"}},"title":{"id":"Kaca tema gelap: lempeng lebih terang dari kartu, sorot atas, sisi lembut","en":"Dark-theme glass: slab brighter than the card, top highlight, soft sides"},"detail":{"id":"Analisis dev.9: isi hampir sama dengan kartu, rim putih 43 L* dan sisi berwarna 52% terbaca sebagai outline, bayangan hitam tak terlihat — tidak ada kesan kaca. Dari lima varian mock, dipilih D: isi +15 L* di atas kartu memudar ke bawah, lensa kiri kuat, sorot 1 px di dalam tepi atas, rim atas terang → bawah redup, sisi berwarna 30%/14%, bayangan hitam ke bawah (−5 L*).","en":"dev.9 analysis: fill nearly equal to the card, a 43 L* white rim and 52% coloured sides read as an outline, black shadow invisible — no glass feel. Of five mock variants, D was chosen: fill +15 L* above the card fading downward, strong left lens, 1 px inner top highlight, bright top rim → dim bottom, coloured sides 30%/14%, black downward shadow (−5 L*)."}}]},{"version":"1.1.0-dev.9","date":"2026-10-15","summary":{"id":"Bayangan kaca netral & lebih rendah; warna penanda diaudit terhadap Kamus Penanda (teks chip netral, hanya titik berwarna); toggle tema tanpa ikon; tombol header tanpa blok hover.","en":"Neutral, lower glass shadow; indicator colours audited against the Indicator Guide (neutral chip text, only the dot coloured); theme toggle without icon; header buttons without hover block."},"entries":[{"id":"dev9-shadow","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · kartu metrik & daftar pekerjaan","en":"Dashboard · metric cards & work list"}},"title":{"id":"Bayangan pil & chip: netral dan tidak melayang","en":"Pill & chip shadow: neutral and grounded"},"detail":{"id":"Semu warna indikator pada bayangan dihapus; offset/blur dikurangi (pil 2/6 px, chip 1/4 px). Profil di bawah tepi: pil 91·94·96·97 (dev.8: 86·89·91·92), chip 93·97·97.","en":"Indicator tint removed from the shadow; offset/blur reduced (pill 2/6 px, chip 1/4 px). Profile below the edge: pill 91·94·96·97 (dev.8: 86·89·91·92), chip 93·97·97."}},{"id":"dev9-tones","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · daftar pekerjaan; Label","en":"Dashboard · work list; Labels"}},"title":{"id":"Warna penanda mengikuti Kamus Penanda; teks chip netral","en":"Indicator colours follow the Indicator Guide; neutral chip text"},"detail":{"id":"Aturan kamus: biru = menunggu/diproses, oranye = perlu tindakan, merah = lewat tenggat, hijau = selesai, netral = ditutup/kedaluwarsa. Diperbaiki: \"Baru\" dan \"Diajukan\" (tiket) tadinya netral → biru; penanda akses di halaman Label (Normal/Dibatasi/Ditangguhkan) tadinya di luar sistem status (kuning lain, tanpa titik) → netral/oranye/merah dengan titik. Pada chip kaca hanya titik dan rim yang berwarna; teks memakai warna teks biasa.","en":"Guide rule: blue = waiting/processing, orange = action needed, red = past deadline, green = done, neutral = closed/expired. Fixed: \"New\" and \"Submitted\" (tickets) were neutral → blue; access indicators on the Labels page (Normal/Limited/Suspended) sat outside the status system (different yellow, no dot) → neutral/orange/red with a dot. On glass chips only the dot and rim carry the colour; text uses the normal text colour."}},{"id":"dev9-header","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Header","en":"Header"}},"title":{"id":"Toggle tema tanpa ikon; tombol bahasa/notifikasi/chat/profil tanpa blok hover","en":"Theme toggle without icon; language/notification/chat/profile buttons without hover block"},"detail":{"id":"Ikon matahari/bulan di dalam knop disembunyikan. Latar hover pada empat tombol header dihapus; fokus keyboard tetap diberi garis luar.","en":"The sun/moon icon inside the knob is hidden. Hover background on the four header buttons removed; keyboard focus still shows an outline."}}]},{"version":"1.1.0-dev.8","date":"2026-10-15","summary":{"id":"Kaca v4: lensa di sisi kiri, rim berwarna indikator di kiri–kanan untuk pil DAN chip status, bayangan diukur ulang terhadap referensi baru.","en":"Glass v4: left-side lens, indicator-coloured rim on left/right for the pill AND status chips, shadow re-measured against the new references."},"entries":[{"id":"dev8-glass-pill","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · kartu metrik","en":"Dashboard · metric cards"}},"title":{"id":"Pil kaca v4: lensa kiri + rim berwarna di kiri–kanan","en":"Glass pill v4: left lens + coloured rim on both sides"},"detail":{"id":"Referensi pil 15% diukur per 1 px: isi di sisi kiri lebih gelap 3 L* dari latar (lensa), rim putih di atas & bawah, warna indikator kuat di kiri dan lembut di kanan, bayangan hanya ke bawah. Hasil kami vs referensi: bayangan 86·89·91·92·93 (ref 89·91·92·93·94), garis kiri 81 (ref 82), isi kiri 94–95 (ref 95), garis kanan 94 (ref 94).","en":"The 15% reference pill measured per CSS px: left fill 3 L* darker than the page (lens), white rim top & bottom, strong indicator colour on the left and soft on the right, downward-only shadow. Ours vs reference: shadow 86·89·91·92·93 (ref 89·91·92·93·94), left line 81 (ref 82), left fill 94–95 (ref 95), right line 94 (ref 94)."}},{"id":"dev8-chips","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · daftar pekerjaan","en":"Dashboard · work list"}},"title":{"id":"Chip status memakai resep yang sama: warna indikator di sisi kiri & kanan","en":"Status chips use the same recipe: indicator colour on the left & right sides"},"detail":{"id":"Chip tidak punya pseudo-elemen bebas (::before = titik status, ::after dimatikan), jadi rim digambar lewat border transparan 1 px + lapisan border-box. Profil vs referensi chip: tepi atas putih 100, isi 99→98, bayangan 89·92·93·94 (ref 91·93·94·95). Tema gelap memakai alas kartu opak agar rim tidak tembus ke dalam chip.","en":"Chips have no free pseudo-element (::before = status dot, ::after disabled), so the rim is drawn via a 1 px transparent border + border-box layers. Profile vs the reference chip: white top 100, fill 99→98, shadow 89·92·93·94 (ref 91·93·94·95). Dark theme uses an opaque card base so the rim does not show through the chip."}}]},{"version":"1.1.0-dev.7","date":"2026-10-15","summary":{"id":"Kaca v3 yang diukur sampai cocok dengan referensi; header jadi kartu berjarak dari atas + bar kaca penuh saat scroll; toggle & slider bergaya fisik; tombol kartu seragam; kartu penarikan tanpa tombol.","en":"Glass v3 measured until it matches the reference; header as an inset card + full-width glass bar on scroll; physical toggle & switch; uniform card buttons; withdrawal card without a button."},"entries":[{"id":"dev7-glass","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · kartu metrik","en":"Dashboard · metric cards"}},"title":{"id":"Pil kaca cocok dengan referensi (diukur)","en":"Glass pill matches the reference (measured)"},"detail":{"id":"Profil kecerahan pil dibandingkan angka per angka dengan referensi: tepi atas putih 100, isi 99→97, tepi bawah 86 (ref 89), garis kiri 81 (ref 82). Pil lebih lapang (26 px), tanpa cincin abu, bayangan hanya ke bawah.","en":"Pill brightness profile compared number by number with the reference: white top rim 100, fill 99→97, bottom edge 86 (ref 89), left line 81 (ref 82). Roomier pill (26 px), no grey ring, downward-only shadow."}},{"id":"dev7-header","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · header","en":"Dashboard · header"}},"title":{"id":"Header jadi kartu berjarak dari tepi atas","en":"Header becomes an inset card"},"detail":{"id":"Isi tetap (sapaan + Wawasan); bentuknya kartu bersudut 26 px dengan jarak 12 px dari atas & samping. Saat digulir > 140 px melipat jadi bar penuh kiri–kanan berkaca; mengembang lagi di puncak.","en":"Content unchanged (greeting + Insights); the frame is a 26 px rounded card inset 12 px from the top and sides. Scrolling past 140 px folds it into a full-width glass bar; it expands again at the top."}},{"id":"dev7-controls","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Header · toggle tema & slider Platform–Staf","en":"Header · theme toggle & Platform–Staff switch"}},"title":{"id":"Toggle tema & slider Platform–Staf bergaya fisik","en":"Physical-style theme toggle & workspace switch"},"detail":{"id":"Track cekung, knob cembung dengan sorotan & bayangan lembut, gerak memantul ringan; warna netral.","en":"Concave track, convex knob with highlight & soft shadow, slight bounce; neutral colours."}},{"id":"dev7-buttons","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · kartu statistik & metrik","en":"Dashboard · stat & metric cards"}},"title":{"id":"Tombol buka/tutup seragam: hover hitam, chevron memantul, panel mengembang","en":"Uniform open/close buttons: black hover, bouncing chevron, expanding panel"},"detail":{"id":"Tombol metrik ikut aturan hover kartu lain (hitam di terang, putih di gelap); tombol kartu statistik & tenggat memakai animasi yang sama. Kartu Penarikan periode ini tidak lagi punya tombol rincian.","en":"The metric button follows the other cards' hover rule (black in light, white in dark); stat and deadline card buttons use the same animation. The period-withdrawal card no longer has a details button."}}]},{"version":"1.1.0-dev.6","date":"2026-10-15","summary":{"id":"Resep kaca ditulis ulang dari profil piksel referensi; chip status kecil di samping nama; seal label terverifikasi di mana pun; animasi buka/tutup; klik menu 2× lebih ringan.","en":"Glass recipe rebuilt from the reference pixel profile; small status chips beside the title; verified-label seal everywhere; open/close animation; menu clicks twice as light."},"entries":[{"id":"dev6-glass","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · kartu metrik","en":"Dashboard · metric cards"}},"title":{"id":"Pil & tooltip kaca seperti referensi","en":"Glass pills & tooltips like the reference"},"detail":{"id":"Isi gradien putih (lensa), rim atas putih, semu warna hanya di sisi segitiga, bayangan lembut ke bawah; urutan segitiga lalu angka.","en":"White gradient fill (lens), white top rim, colour tint only on the triangle side, soft downward shadow; triangle before the number."}},{"id":"dev6-chips","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · Antrean & Pekerjaan Saya","en":"Dashboard · Queue & My Work"}},"title":{"id":"Chip status kecil tepat setelah nama pekerjaan","en":"Small status chips right after the work title"},"detail":{"id":"11 px, resep kaca yang sama, bersemu warna statusnya.","en":"11 px, same glass recipe, tinted with the status colour."}},{"id":"dev6-seal","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · daftar pekerjaan","en":"Dashboard · work lists"}},"title":{"id":"Seal terverifikasi di mana pun nama label tampil","en":"Verified seal wherever a label name appears"},"detail":{"id":"Nama label terverifikasi (mis. Awan Records) selalu diikuti seal — daftar pekerjaan, sidebar, dialog.","en":"Verified label names are always followed by the seal — work lists, sidebar, dialogs."}},{"id":"dev6-motion","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · kartu metrik","en":"Dashboard · metric cards"}},"title":{"id":"Animasi buka/tutup rincian metrik","en":"Metric detail open/close animation"},"detail":{"id":"Panel mengembang 380 ms, isi muncul bertahap, batang menggambar diri; tutup 200 ms; chevron memantul ringan. Mengikuti prefers-reduced-motion.","en":"Panel expands in 380 ms, content staggers in, bars draw themselves; closes in 200 ms; chevron bounces slightly. Honours prefers-reduced-motion."}},{"id":"dev6-inp","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Seluruh preview","en":"Whole preview"}},"title":{"id":"Klik menu lebih ringan: simpan ditunda 300 ms","en":"Lighter menu clicks: saves deferred by 300 ms"},"detail":{"id":"Setiap klik dulu men-serialisasi ±7 MB data (INP 400–540 ms). Kini simpan digabung 300 ms setelah aksi; transaksi atomik tetap seketika. Klik Dashboard 358 → 182 ms.","en":"Each click used to serialise ±7 MB of data (INP 400–540 ms). Saves are now batched 300 ms after the action; atomic transactions stay immediate. Dashboard click 358 → 182 ms."}}]},{"version":"1.1.0-dev.5","date":"2026-10-15","summary":{"id":"Detail kaca dari referensi pemilik: kartu lembut, pil persentase & tooltip kaca bersemu warna, progress tebal bergaris. Eksplorasi warna merek dihapus. Klik pertama di Studio kini berhasil.","en":"Glass details from the owner reference: soft cards, tinted glass percentage pills & tooltips, thick striped progress. Brand colour exploration removed. First Studio click now works."},"entries":[{"id":"dev5-card","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard","en":"Dashboard"}},"title":{"id":"Kartu lembut: selisih +3 L* dari latar","en":"Soft cards: +3 L* step above the background"},"detail":{"id":"Terang #F8F8F8 di atas #F0F0F0, gelap #171718 di atas #0A0A0B — langkah kecerahan yang sama dengan referensi; tepi = garis bayangan 1 px + sorotan 1 px.","en":"Light #F8F8F8 on #F0F0F0, dark #171718 on #0A0A0B — the same perceptual step as the reference; edge = 1 px shadow line + 1 px highlight."}},{"id":"dev5-glass","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · kartu metrik","en":"Dashboard · metric cards"}},"title":{"id":"Pil persentase kaca bersemu warna metrik","en":"Glass percentage pill tinted by the metric colour"},"detail":{"id":"Angka warna teks, segitiga hijau/merah; tepi kiri & bayangan bersemu warna yang sama. Chip status di daftar pekerjaan memakai resep yang sama.","en":"Text-coloured number, green/red triangle; left edge & shadow tinted with the same colour. Status chips in the work lists use the same recipe."}},{"id":"dev5-tooltip","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · Penarikan periode ini","en":"Dashboard · Period withdrawals"}},"title":{"id":"Progress tebal bergaris + tooltip kaca","en":"Thick striped progress + glass tooltip"},"detail":{"id":"Batang 14 px bergaris diagonal hijau dengan penanda di ujung; arahkan kursor untuk “75,6% · Rp 75.000.000 dibayarkan”. Nominal ringkas di kartu metrik juga menampilkan angka lengkap saat diarahkan.","en":"14 px bar with green diagonal stripes and an end marker; hover for “75.6% · Rp 75,000,000 paid”. Abbreviated metric values also reveal the full number on hover."}},{"id":"dev5-studio-fix","status":"prototype","where":{"role":"super","page":"dashboard","theme":"dark","menu":{"id":"Studio Pratinjau","en":"Preview Studio"}},"title":{"id":"Klik pertama di Studio kini berhasil","en":"First Studio click now works"},"detail":{"id":"Titik pulih Studio (8,5 MB) melebihi kuota localStorage sehingga skenario pertama selalu gagal diam-diam — kini cukup disimpan di memori.","en":"The Studio checkpoint (8.5 MB) exceeded the localStorage quota so the first scenario always failed silently — it is now kept in memory."}}]},{"version":"1.1.0-dev.4","date":"2026-10-14","summary":{"id":"Masukan dev 3: kartu metrik ringkas dengan rincian buka/tutup, preview jauh lebih cepat, entri tema gelap di Studio diperbaiki.","en":"dev 3 feedback: compact metric cards with expandable details, much faster preview, Studio dark-theme entry fixed."},"entries":[{"id":"dev4-metric-inline","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard · kartu metrik","en":"Dashboard · metric cards"}},"title":{"id":"Rincian metrik buka/tutup di bawah kartu","en":"Metric details expand below the cards"},"detail":{"id":"Klik kartu untuk membuka perbandingan periode (tanpa popup). Kartu 20% lebih pendek; nominal besar diringkas (Rp 151,6 jt).","en":"Click a card to expand the period comparison (no popup). Cards are 20% shorter; large amounts are abbreviated."}},{"id":"dev4-speed","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Seluruh preview","en":"Whole preview"}},"title":{"id":"Preview lebih cepat, tanpa perjalanan versi","en":"Faster preview, no version run-through"},"detail":{"id":"Tampil 12,8 → 8,8 dtk (kunjungan ulang 9,8 → 6,2 dtk); setiap gambar ulang 467 → 189 ms. Judul tab & label versi tidak lagi berganti saat memuat.","en":"Shows in 8.8 s instead of 12.8 s (repeat visits 6.2 s); each re-render 189 ms instead of 467 ms. Tab title and version label no longer cycle while loading."}}]},{"version":"1.1.0-dev.3","date":"2026-10-14","summary":{"id":"Fondasi tampilan baru, diuji di Dashboard Super & Admin: font Geist, skala tulisan tanpa tebal, tema gelap lebih pekat, persentase metrik sebaris.","en":"New look foundation, trialled on the Super & Admin dashboards: Geist font, weight-light type scale, deeper dark theme, inline metric percentages."},"entries":[{"id":"dev3-type","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard","en":"Dashboard"}},"title":{"id":"Font Geist + skala tulisan baru","en":"Geist font + new type scale"},"detail":{"id":"7 ukuran (12–40) dengan berat 400/500 saja; penekanan lewat ukuran & warna. Font 18 KB. Baru di Dashboard.","en":"7 sizes (12–40), weights 400/500 only; emphasis through size and colour. 18 KB font. Dashboard only for now."}},{"id":"dev3-dark","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard (tema gelap)","en":"Dashboard (dark theme)"},"theme":"dark"},"title":{"id":"Tema gelap lebih pekat","en":"Deeper dark theme"},"detail":{"id":"Latar #0A0A0B, kartu #141415 bertepi tipis — berlaku di seluruh halaman tema gelap.","en":"Background #0A0A0B, cards #141415 with a hairline border — applies to every dark-theme page."}},{"id":"dev3-metric","status":"prototype","where":{"role":"admin","page":"dashboard","menu":{"id":"Dashboard · kartu metrik","en":"Dashboard · metric cards"}},"title":{"id":"Persentase metrik di samping angka","en":"Metric percentage beside the value"},"detail":{"id":"+12% ↗ hijau, −8,1% ↘ merah, 0% → abu-abu; keterangan periode tetap di bawah.","en":"+12% ↗ green, −8.1% ↘ red, 0% → grey; the period caption stays below."}}]},{"version":"1.1.0-dev.2","date":"2026-10-14","summary":{"id":"Preview lebih ringan: berkas besar dimuat belakangan.","en":"Lighter preview: large files load later."},"entries":[{"id":"dev2-lazy-load","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard","en":"Dashboard"}},"title":{"id":"Muatan awal preview turun 35%","en":"Initial preview payload down 35%"},"detail":{"id":"Data bank/wilayah dan pembuat PDF kontrak (1,4 MB) diunduh setelah tampilan muncul; tampil ±15% lebih cepat di jaringan HP.","en":"Bank/region data and the contract PDF maker (1.4 MB) download after the screen appears; about 15% faster on mobile networks."}}]},{"version":"1.1.0-dev.1","date":"2026-10-14","summary":{"id":"Titik awal v1.1: audit keamanan & uang, ikon verifikasi baru, data contoh disamarkan.","en":"v1.1 starting point: security & money audit, new verification badge, pseudonymised sample data."},"entries":[{"id":"dev1-verified-badge","status":"both","where":{"role":"super","page":"labels9","menu":{"id":"Manajemen Label","en":"Label Management"}},"title":{"id":"Ikon verifikasi label baru","en":"New label verification badge"},"detail":{"id":"Bintang datar 11 ujung sesuai referensi; centang transparan mengikuti warna latar.","en":"Flat 11-point star per the reference; the check is transparent and shows the background."}},{"id":"dev1-sample-data","status":"prototype","where":{"role":"super","page":"labels9","menu":{"id":"Manajemen Label","en":"Label Management"}},"title":{"id":"Data contoh memakai nama samaran","en":"Sample data uses pseudonyms"},"detail":{"id":"Nama label, artis, email, WA dan alamat asli diganti samaran; nominal dan status tetap.","en":"Real label, artist, email, phone and address values are replaced; amounts and statuses are kept."}},{"id":"dev1-boot","status":"prototype","where":{"role":"super","page":"dashboard","menu":{"id":"Dashboard","en":"Dashboard"}},"title":{"id":"Preview terbuka tanpa “perjalanan versi”","en":"Preview opens without the version run-through"},"detail":{"id":"Tampilan muncul sekali dalam kondisi akhir; label versi kini v1.1 · dev N.","en":"The screen appears once in its final state; the version label is now v1.1 · dev N."}},{"id":"dev1-token-addons","status":"app","where":null,"title":{"id":"Pembayaran token tidak lagi melunasi add-on","en":"Token payments no longer settle add-ons"},"detail":{"id":"Invoice berisi add-on dibayar rupiah; token hanya untuk biaya rilisan.","en":"Invoices with add-ons are paid in rupiah; tokens cover the release fee only."}},{"id":"dev1-money-guards","status":"app","where":null,"title":{"id":"Pengaman uang: bayar, refund, withdraw","en":"Money guards: pay, refund, withdraw"},"detail":{"id":"Klik ganda tidak memotong token dua kali, tidak ada refund ganda, withdraw yang sudah dibayar tidak bisa ditolak ulang.","en":"Double clicks never spend twice, no double refunds, paid withdrawals cannot be rejected again."}},{"id":"dev1-staff-preview","status":"app","where":null,"title":{"id":"Pratinjau akses staf lebih aman","en":"Safer staff access preview"},"detail":{"id":"Keluar akun berfungsi saat pratinjau; menu khusus Super Admin tersembunyi selama pratinjau.","en":"Sign-out works during preview; Super Admin-only menus stay hidden while previewing."}}]}];
